INSERT INTO lp_vaccines (key, short_name, name, protects_against, common_reactions, notes, sort_order) VALUES
  ('hepb_birth', 'HepB birth', '{"en":"Hepatitis B birth dose","bn":"হেপাটাইটিস-বি জন্মডোজ"}'::jsonb, '{"en":"Hepatitis B, especially infection passed from mother to baby around birth","bn":"হেপাটাইটিস-বি, বিশেষ করে জন্মের সময় মা থেকে শিশুর সংক্রমণ"}'::jsonb, '{"en":"Soreness where the injection was given; sometimes a mild fever.","bn":"ইনজেকশনের জায়গায় ব্যথা; কখনো হালকা জ্বর।"}'::jsonb, '{"en":"Best given within 24 hours of birth. The later hepatitis B doses still come free in the EPI Penta vaccine. If the mother has hepatitis B, tell the doctor before the birth — the baby may also need an immunoglobulin injection.","bn":"জন্মের ২৪ ঘণ্টার মধ্যে দেওয়াই সবচেয়ে ভালো। পরের হেপাটাইটিস-বি ডোজগুলো ইপিআইয়ের পেন্টা টিকায় বিনামূল্যেই পাওয়া যায়। মায়ের হেপাটাইটিস-বি থাকলে প্রসবের আগেই ডাক্তারকে জানান — শিশুর একটি ইমিউনোগ্লোবুলিন ইনজেকশনও লাগতে পারে।"}'::jsonb, 20),
  ('rota', 'Rota', '{"en":"Rotavirus vaccine","bn":"রোটাভাইরাস টিকা"}'::jsonb, '{"en":"Rotavirus, a common cause of severe diarrhoea and dehydration in babies and young children","bn":"রোটাভাইরাস — শিশুদের মারাত্মক ডায়রিয়া ও পানিশূন্যতার একটি সাধারণ কারণ"}'::jsonb, '{"en":"Given by mouth. Mild fussiness, loose stools or vomiting for a day or two can happen.","bn":"মুখে খাওয়ানো হয়। এক-দুই দিন হালকা অস্থিরতা, পাতলা পায়খানা বা বমি হতে পারে।"}'::jsonb, '{"en":"Brands differ: some need 2 doses, others 3. Very rarely it is linked to a bowel blockage (intussusception) in the week after a dose — go to hospital at once if the baby has bouts of hard crying while drawing up the legs, keeps vomiting, or has blood in the stool.","bn":"ব্র্যান্ডভেদে ২ বা ৩ ডোজ লাগে। খুব কম ক্ষেত্রে ডোজের পরের সপ্তাহে অন্ত্রে প্যাঁচ লাগা (ইনটাসাসেপশন) দেখা দিতে পারে — শিশু পা গুটিয়ে থেকে থেকে খুব কাঁদলে, বারবার বমি করলে বা পায়খানায় রক্ত গেলে সাথে সাথে হাসপাতালে যান।"}'::jsonb, 21),
  ('hepa', 'HepA', '{"en":"Hepatitis A vaccine","bn":"হেপাটাইটিস-এ টিকা"}'::jsonb, '{"en":"Hepatitis A, a liver infection spread through contaminated food and water and one cause of jaundice in children","bn":"হেপাটাইটিস-এ — দূষিত খাবার ও পানির মাধ্যমে ছড়ানো লিভারের সংক্রমণ, শিশুদের জন্ডিসের একটি কারণ"}'::jsonb, '{"en":"Sore arm, tiredness or a mild fever for a day.","bn":"হাতে ব্যথা, ক্লান্তি বা একদিন হালকা জ্বর।"}'::jsonb, '{"en":"Some brands need two doses, others one. Safe water, handwashing with soap and clean food also protect against hepatitis A and E.","bn":"কিছু ব্র্যান্ডে দুই ডোজ লাগে, কিছুতে এক ডোজ। নিরাপদ পানি, সাবান দিয়ে হাত ধোয়া আর পরিষ্কার খাবারও হেপাটাইটিস-এ ও ই থেকে রক্ষা করে।"}'::jsonb, 22),
  ('varicella', 'Varicella', '{"en":"Chickenpox (varicella) vaccine","bn":"জলবসন্ত (ভ্যারিসেলা) টিকা"}'::jsonb, '{"en":"Chickenpox","bn":"জলবসন্ত (চিকেনপক্স)"}'::jsonb, '{"en":"Sore arm or mild fever; a few chickenpox-like spots can appear within a month.","bn":"হাতে ব্যথা বা হালকা জ্বর; এক মাসের মধ্যে জলবসন্তের মতো কয়েকটা দানা উঠতে পারে।"}'::jsonb, '{"en":"This is a live vaccine. Tell the doctor if your child has a weak immune system or takes medicines that lower immunity, such as steroids or cancer treatment.","bn":"এটি জীবিত (লাইভ) টিকা। সন্তানের রোগ প্রতিরোধ ক্ষমতা দুর্বল হলে বা প্রতিরোধ ক্ষমতা কমায় এমন ওষুধ — যেমন স্টেরয়েড বা ক্যান্সারের চিকিৎসা — চললে ডাক্তারকে জানান।"}'::jsonb, 23),
  ('flu', 'Flu', '{"en":"Influenza (flu) vaccine","bn":"ইনফ্লুয়েঞ্জা (ফ্লু) টিকা"}'::jsonb, '{"en":"Seasonal influenza","bn":"মৌসুমি ইনফ্লুয়েঞ্জা"}'::jsonb, '{"en":"Sore arm, low fever or aches for a day or two.","bn":"এক-দুই দিন হাতে ব্যথা, হালকা জ্বর বা গা ব্যথা।"}'::jsonb, '{"en":"Flu viruses change, so a new vaccine is needed every year. It is especially useful for children with asthma, heart or lung disease, or another long-term illness.","bn":"ফ্লুর ভাইরাস বদলায়, তাই প্রতি বছর নতুন টিকা লাগে। হাঁপানি, হৃদরোগ, ফুসফুসের রোগ বা অন্য দীর্ঘমেয়াদি অসুখ থাকলে এটি বিশেষ উপকারী।"}'::jsonb, 24),
  ('mmr', 'MMR', '{"en":"MMR (measles-mumps-rubella)","bn":"এমএমআর (হাম-মাম্পস-রুবেলা)"}'::jsonb, '{"en":"Measles, mumps and rubella","bn":"হাম, মাম্পস ও রুবেলা"}'::jsonb, '{"en":"Fever or a mild rash about 7–12 days after the dose; sometimes swollen glands. Rarely the fever brings a short fit with fever.","bn":"ডোজের প্রায় ৭–১২ দিন পরে জ্বর বা হালকা র‍্যাশ; কখনো গ্রন্থি ফোলা। খুব কম ক্ষেত্রে জ্বরের সাথে অল্প সময়ের খিঁচুনি হতে পারে।"}'::jsonb, '{"en":"The EPI already gives MR (measles-rubella) free at 9 and 15 months; MMR adds protection against mumps. Ask your doctor how it fits with the EPI doses — do not skip the free MR doses.","bn":"ইপিআই ৯ ও ১৫ মাসে বিনামূল্যে এমআর (হাম-রুবেলা) দেয়; এমএমআর বাড়তি হিসেবে মাম্পস থেকেও রক্ষা করে। ইপিআইয়ের ডোজের সাথে কীভাবে মেলাবেন ডাক্তারকে জিজ্ঞেস করুন — বিনামূল্যের এমআর ডোজ বাদ দেবেন না।"}'::jsonb, 25)
INSERT INTO lp_vaccine_schedules (key, country, kind, name, notes, effective_from, version, source_key, is_default, review_status) VALUES
  ('bd_private_optional', 'BD', 'private', '{"en":"Optional vaccines (private, Bangladesh)","bn":"ঐচ্ছিক টিকা (প্রাইভেট, বাংলাদেশ)"}'::jsonb, '{"en":"Optional vaccines many paediatricians in Bangladesh offer privately, alongside — never instead of — the free EPI schedule. Brands differ in doses and ages; your doctor sets the dates.","bn":"বাংলাদেশে অনেক শিশু বিশেষজ্ঞ প্রাইভেটভাবে এই ঐচ্ছিক টিকাগুলো দেন — বিনামূল্যের ইপিআই সূচির পাশাপাশি, কখনোই তার বদলে নয়। ব্র্যান্ডভেদে ডোজ ও বয়স আলাদা; তারিখ ঠিক করবেন আপনার ডাক্তার।"}'::jsonb, NULL, 1, 'aap_healthychildren', false, 'in_review'::lp_review_status)
INSERT INTO lp_vaccine_doses (schedule_key, vaccine_key, dose_number, label, subject, due_day, latest_day, min_interval_days, due_note, sex, sort_order) VALUES
  ('bd_private_optional', 'hepb_birth', 1, '{"en":"Hep B birth dose","bn":"হেপ-বি জন্মডোজ"}'::jsonb, 'child', 0, NULL, NULL, '{"en":"Within 24 hours of birth, before leaving the hospital if possible. Your doctor decides.","bn":"জন্মের ২৪ ঘণ্টার মধ্যে, সম্ভব হলে হাসপাতাল ছাড়ার আগেই। সিদ্ধান্ত ডাক্তারের।"}'::jsonb, 'any', 1),
  ('bd_private_optional', 'rota', 1, '{"en":"Rota 1","bn":"রোটা-১"}'::jsonb, 'child', 42, 104, NULL, '{"en":"From 6 weeks. The first dose has an upper age limit (often around 15 weeks, depending on the brand), so do not delay — your doctor will confirm.","bn":"৬ সপ্তাহ থেকে। প্রথম ডোজের একটা সর্বোচ্চ বয়সসীমা আছে (ব্র্যান্ডভেদে প্রায়ই ১৫ সপ্তাহের আশেপাশে), তাই দেরি করবেন না — ডাক্তার নিশ্চিত করবেন।"}'::jsonb, 'any', 10),
  ('bd_private_optional', 'rota', 2, '{"en":"Rota 2","bn":"রোটা-২"}'::jsonb, 'child', 70, NULL, 28, '{"en":"About 10 weeks, at least 4 weeks after dose 1. The doctor sets the date by brand.","bn":"প্রায় ১০ সপ্তাহে, প্রথম ডোজের অন্তত ৪ সপ্তাহ পর। ব্র্যান্ড অনুযায়ী তারিখ ঠিক করবেন ডাক্তার।"}'::jsonb, 'any', 11),
  ('bd_private_optional', 'rota', 3, '{"en":"Rota 3 (3-dose brands only)","bn":"রোটা-৩ (শুধু ৩ ডোজের ব্র্যান্ডে)"}'::jsonb, 'child', 98, NULL, 28, '{"en":"About 14 weeks, only for brands with 3 doses. All doses must be finished by the age the brand allows (often 6–8 months).","bn":"প্রায় ১৪ সপ্তাহে, শুধু ৩ ডোজের ব্র্যান্ডে। ব্র্যান্ড যে বয়স পর্যন্ত অনুমতি দেয় (প্রায়ই ৬–৮ মাস), তার মধ্যেই সব ডোজ শেষ করতে হয়।"}'::jsonb, 'any', 12),
  ('bd_private_optional', 'hepa', 1, '{"en":"Hep A 1","bn":"হেপ-এ ১"}'::jsonb, 'child', 365, NULL, NULL, '{"en":"From 12 months. Your doctor decides.","bn":"১২ মাস থেকে। সিদ্ধান্ত ডাক্তারের।"}'::jsonb, 'any', 20),
  ('bd_private_optional', 'hepa', 2, '{"en":"Hep A 2","bn":"হেপ-এ ২"}'::jsonb, 'child', 548, NULL, 183, '{"en":"6–12 months after dose 1, only if the brand needs a second dose; some brands are a single dose.","bn":"প্রথম ডোজের ৬–১২ মাস পর, শুধু যদি ব্র্যান্ডে দ্বিতীয় ডোজ লাগে; কিছু ব্র্যান্ডে এক ডোজই যথেষ্ট।"}'::jsonb, 'any', 21),
  ('bd_private_optional', 'varicella', 1, '{"en":"Chickenpox 1","bn":"জলবসন্ত ১"}'::jsonb, 'child', 365, NULL, NULL, '{"en":"At 12–15 months. Your doctor decides.","bn":"১২–১৫ মাসে। সিদ্ধান্ত ডাক্তারের।"}'::jsonb, 'any', 30),
  ('bd_private_optional', 'varicella', 2, '{"en":"Chickenpox 2","bn":"জলবসন্ত ২"}'::jsonb, 'child', 1461, NULL, 90, '{"en":"Around 4–6 years; some doctors give it earlier, at least 3 months after dose 1.","bn":"প্রায় ৪–৬ বছরে; কোনো কোনো ডাক্তার আগেও দেন, প্রথম ডোজের অন্তত ৩ মাস পর।"}'::jsonb, 'any', 31),
  ('bd_private_optional', 'flu', 1, '{"en":"Flu (first season)","bn":"ফ্লু (প্রথম মৌসুম)"}'::jsonb, 'child', 183, NULL, NULL, '{"en":"From 6 months, then once every year before the flu season. Your doctor decides.","bn":"৬ মাস থেকে, তারপর প্রতি বছর ফ্লুর মৌসুমের আগে একবার। সিদ্ধান্ত ডাক্তারের।"}'::jsonb, 'any', 40),
  ('bd_private_optional', 'flu', 2, '{"en":"Flu (second dose, first season)","bn":"ফ্লু (দ্বিতীয় ডোজ, প্রথম মৌসুম)"}'::jsonb, 'child', 211, NULL, 28, '{"en":"Only in the first season for children under 9: a second dose at least 4 weeks after the first. After that, one dose a year.","bn":"শুধু ৯ বছরের কম শিশুর প্রথম মৌসুমে: প্রথম ডোজের অন্তত ৪ সপ্তাহ পর দ্বিতীয় ডোজ। এরপর বছরে এক ডোজ।"}'::jsonb, 'any', 41),
  ('bd_private_optional', 'mmr', 1, '{"en":"MMR 1","bn":"এমএমআর-১"}'::jsonb, 'child', 365, NULL, NULL, '{"en":"At 12–15 months. Your doctor will space it with the free EPI MR doses at 9 and 15 months.","bn":"১২–১৫ মাসে। ইপিআইয়ের বিনামূল্যের এমআর ডোজের (৯ ও ১৫ মাস) সাথে সময়ের ব্যবধান ডাক্তার ঠিক করবেন।"}'::jsonb, 'any', 50),
  ('bd_private_optional', 'mmr', 2, '{"en":"MMR 2","bn":"এমএমআর-২"}'::jsonb, 'child', 1461, NULL, 28, '{"en":"At 4–6 years. Your doctor decides.","bn":"৪–৬ বছরে। সিদ্ধান্ত ডাক্তারের।"}'::jsonb, 'any', 51)
INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('fa-choking-baby', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '👶', '{"en":"Choking — baby under 1 year","bn":"গলায় কিছু আটকে যাওয়া — ১ বছরের কম শিশু"}'::jsonb, '{"en":"If a baby cannot cry, cough or breathe, act at once: 5 back blows, then 5 chest thrusts, and repeat.","bn":"শিশু কাঁদতে, কাশতে বা শ্বাস নিতে না পারলে সাথে সাথে ব্যবস্থা নিন: পিঠে ৫টি চাপড়, তারপর বুকে ৫টি চাপ — এবং আবার।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Cannot cry, cough or make any sound","Struggling to breathe, or squeaky, noisy breathing","Face or lips turning blue or grey","Was eating or holding a small object just before","Going floppy or not responding"],"bn":["কাঁদতে, কাশতে বা কোনো শব্দ করতে পারছে না","শ্বাস নিতে কষ্ট, বা শ্বাসের সাথে চিঁ চিঁ শব্দ","মুখ বা ঠোঁট নীল বা ধূসর হয়ে যাচ্ছে","এইমাত্র কিছু খাচ্ছিল বা ছোট কোনো জিনিস হাতে ছিল","নেতিয়ে পড়ছে বা সাড়া দিচ্ছে না"]},"do_now":{"en":["If the baby is coughing strongly, let them cough — it is the best way to clear the throat. Stay and watch.","If they cannot cough, cry or breathe, shout for help and ask someone to call 999.","Back blows: lay the baby face down along your forearm or thigh, head lower than the bottom, holding the jaw and head with your hand.","Give up to 5 firm blows between the shoulder blades with the heel of your other hand. Check the mouth after each one.","Chest thrusts: turn the baby face up along your arm or thigh, head lower. Put two fingers in the middle of the chest, just below the nipple line, and push down sharply up to 5 times.","If you can see the object and it is easy to reach, pick it out with your fingertips.","Keep repeating 5 back blows and 5 chest thrusts until the object comes out or help arrives.","If the baby stops responding, call 999 now and start baby CPR if you have been trained.","Even if the object comes out, take the baby to a doctor to be checked."],"bn":["শিশু জোরে কাশলে কাশতে দিন — গলা পরিষ্কারের এটাই সবচেয়ে ভালো উপায়। পাশে থেকে খেয়াল রাখুন।","কাশতে, কাঁদতে বা শ্বাস নিতে না পারলে চিৎকার করে সাহায্য ডাকুন, কাউকে ৯৯৯-এ ফোন করতে বলুন।","পিঠে চাপড়: শিশুকে উপুড় করে আপনার হাতের বাহু বা উরুর ওপর শোয়ান, মাথা নিতম্বের চেয়ে নিচে রাখুন, এক হাতে চোয়াল ও মাথা ধরে রাখুন।","অন্য হাতের তালুর গোড়া দিয়ে দুই কাঁধের হাড়ের মাঝখানে জোরে ৫টি পর্যন্ত চাপড় দিন। প্রতিবার পর মুখের ভেতর দেখুন।","বুকে চাপ: শিশুকে চিত করে হাত বা উরুর ওপর শোয়ান, মাথা নিচের দিকে। বুকের মাঝখানে, দুই বোঁটার রেখার ঠিক নিচে দুই আঙুল রেখে জোরে নিচের দিকে ৫ বার পর্যন্ত চাপ দিন।","জিনিসটা চোখে দেখা গেলে আর সহজে নাগাল পেলে আঙুলের ডগা দিয়ে বের করে আনুন।","জিনিসটা বের না হওয়া বা সাহায্য না আসা পর্যন্ত ৫টি চাপড় আর ৫টি বুকে চাপ পালা করে দিতে থাকুন।","শিশু সাড়া দেওয়া বন্ধ করলে এখনই ৯৯৯-এ ফোন করুন, প্রশিক্ষণ থাকলে শিশুর সিপিআর শুরু করুন।","জিনিসটা বের হয়ে গেলেও শিশুকে ডাক্তার দেখিয়ে নিন।"]},"avoid":{"en":["Do not sweep your finger blindly inside the mouth — it can push the object further down.","Do not hold the baby upside down by the legs and shake them.","Do not use tummy (abdominal) thrusts on a baby under 1 year.","Do not give water, food or anything else to swallow."],"bn":["না দেখে মুখের ভেতর আঙুল ঢুকিয়ে হাতড়াবেন না — জিনিসটা আরও ভেতরে চলে যেতে পারে।","শিশুকে পা ধরে উল্টো করে ঝাঁকাবেন না।","১ বছরের কম শিশুর পেটে চাপ (অ্যাবডমিনাল থ্রাস্ট) দেবেন না।","পানি, খাবার বা গেলার মতো কিছু দেবেন না।"]},"seek_help":{"en":["Call 999 or go to the nearest hospital if the object does not come out or the baby stops responding.","See a doctor the same day after any choking episode, even if the baby seems well — a piece may still be stuck, and chest thrusts can cause injury.","Learn baby first aid and CPR from a trained instructor before you need it."],"bn":["জিনিসটা বের না হলে বা শিশু সাড়া না দিলে ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালে যান।","গলায় আটকানোর যেকোনো ঘটনার পর শিশু ভালো মনে হলেও সেদিনই ডাক্তার দেখান — কোনো টুকরো এখনো আটকে থাকতে পারে, আর বুকে চাপে আঘাত লাগতে পারে।","দরকার পড়ার আগেই প্রশিক্ষিত কারো কাছ থেকে শিশুর প্রাথমিক চিকিৎসা ও সিপিআর শিখে রাখুন।"]}}'::jsonb, 2, 0, 365, '{}'::text[], 'any', ARRAY['choking', 'baby', 'back blows', 'chest thrusts', 'first aid']::text[], false, 'in_review'::lp_review_status, 10201),
  ('fa-choking-child', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🧒', '{"en":"Choking — child over 1 year","bn":"গলায় কিছু আটকে যাওয়া — ১ বছরের বেশি শিশু"}'::jsonb, '{"en":"If a child cannot speak, cough or breathe: up to 5 back blows, then up to 5 abdominal thrusts, and repeat.","bn":"শিশু কথা বলতে, কাশতে বা শ্বাস নিতে না পারলে: পিঠে ৫টি পর্যন্ত চাপড়, তারপর পেটে ৫টি পর্যন্ত চাপ — এবং আবার।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Holding the throat, cannot speak, cough or breathe","Noisy or squeaky breathing, or no sound at all","Lips or face turning blue","Was eating or playing with something small just before","Going floppy or not responding"],"bn":["গলা চেপে ধরে আছে, কথা বলতে, কাশতে বা শ্বাস নিতে পারছে না","শ্বাসে শব্দ বা চিঁ চিঁ আওয়াজ, অথবা কোনো শব্দই নেই","ঠোঁট বা মুখ নীল হয়ে যাচ্ছে","এইমাত্র কিছু খাচ্ছিল বা ছোট কিছু নিয়ে খেলছিল","নেতিয়ে পড়ছে বা সাড়া দিচ্ছে না"]},"do_now":{"en":["If the child can cough, encourage them to keep coughing and stay with them.","If they cannot cough, speak or breathe, shout for help and ask someone to call 999.","Back blows: lean the child forwards (a small child can lie face down across your lap) and give up to 5 firm blows between the shoulder blades with the heel of your hand.","Check the mouth; take the object out only if you can see it and reach it easily.","Abdominal thrusts: stand or kneel behind the child, put your arms around the upper tummy, make a fist between the belly button and the bottom of the breastbone, hold it with your other hand and pull sharply inwards and upwards, up to 5 times.","Keep repeating 5 back blows and 5 abdominal thrusts until the object comes out or help arrives.","If the child stops responding, call 999 and start CPR if you have been trained.","After any abdominal thrusts, take the child to a doctor, even if they seem fine."],"bn":["শিশু কাশতে পারলে কাশতে উৎসাহ দিন আর পাশে থাকুন।","কাশতে, কথা বলতে বা শ্বাস নিতে না পারলে চিৎকার করে সাহায্য ডাকুন, কাউকে ৯৯৯-এ ফোন করতে বলুন।","পিঠে চাপড়: শিশুকে সামনের দিকে ঝুঁকিয়ে দিন (ছোট শিশুকে কোলের ওপর উপুড় করে শোয়ানো যায়), তারপর হাতের তালুর গোড়া দিয়ে দুই কাঁধের হাড়ের মাঝখানে জোরে ৫টি পর্যন্ত চাপড় দিন।","মুখের ভেতর দেখুন; জিনিসটা চোখে দেখা গেলে আর সহজে নাগাল পেলে তবেই বের করুন।","পেটে চাপ: শিশুর পেছনে দাঁড়ান বা হাঁটু গেড়ে বসুন, দুই হাতে পেটের ওপরের অংশ জড়িয়ে ধরুন, নাভি আর বুকের হাড়ের নিচের প্রান্তের মাঝখানে এক হাতের মুঠি রাখুন, অন্য হাতে মুঠিটা ধরে ভেতরের ও ওপরের দিকে জোরে টান দিন — ৫ বার পর্যন্ত।","জিনিসটা বের না হওয়া বা সাহায্য না আসা পর্যন্ত ৫টি চাপড় আর ৫টি পেটে চাপ পালা করে দিতে থাকুন।","শিশু সাড়া দেওয়া বন্ধ করলে ৯৯৯-এ ফোন করুন, প্রশিক্ষণ থাকলে সিপিআর শুরু করুন।","পেটে চাপ দেওয়া হলে শিশু ভালো মনে হলেও ডাক্তার দেখান।"]},"avoid":{"en":["Do not sweep your finger blindly inside the mouth.","Do not give abdominal thrusts to a baby under 1 year.","Do not hit the back of a child who is coughing well — let the cough work.","Do not give water or food until breathing is completely normal."],"bn":["না দেখে মুখের ভেতর আঙুল দিয়ে হাতড়াবেন না।","১ বছরের কম শিশুর পেটে চাপ দেবেন না।","শিশু ভালোভাবে কাশতে পারলে পিঠে চাপড় দেবেন না — কাশিকেই কাজ করতে দিন।","শ্বাস পুরোপুরি স্বাভাবিক না হওয়া পর্যন্ত পানি বা খাবার দেবেন না।"]},"seek_help":{"en":["Go to hospital after abdominal thrusts — they can injure the inside of the tummy.","See a doctor if a cough, noisy breathing or trouble swallowing continues after the object came out.","Keep small objects, coins, button batteries, nuts and hard sweets away from young children."],"bn":["পেটে চাপ দেওয়ার পর হাসপাতালে নিয়ে যান — এতে পেটের ভেতরে আঘাত লাগতে পারে।","জিনিসটা বের হওয়ার পরও কাশি, শ্বাসে শব্দ বা গিলতে কষ্ট থাকলে ডাক্তার দেখান।","ছোট জিনিস, কয়েন, বোতাম ব্যাটারি, বাদাম ও শক্ত লজেন্স ছোট শিশুর নাগালের বাইরে রাখুন।"]}}'::jsonb, 2, 365, NULL, '{}'::text[], 'any', ARRAY['choking', 'child', 'back blows', 'abdominal thrusts', 'first aid']::text[], false, 'in_review'::lp_review_status, 10202),
  ('fa-drowning', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🌊', '{"en":"Drowning and near-drowning","bn":"পানিতে ডোবা"}'::jsonb, '{"en":"Get the child out safely, check breathing, start rescue breaths and CPR if you are trained, and always go to hospital — even if they seem fine.","bn":"নিরাপদে শিশুকে পানি থেকে তুলুন, শ্বাস দেখুন, প্রশিক্ষণ থাকলে কৃত্রিম শ্বাস ও সিপিআর দিন, আর সবসময় হাসপাতালে নিন — ভালো মনে হলেও।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Taken out of water — a pond, ditch, river, bucket or bath","Not breathing, or not breathing normally","Unconscious or very drowsy","Coughing, breathless or vomiting after being in water","Cold, pale or blue skin or lips"],"bn":["পানি থেকে তোলা হয়েছে — পুকুর, ডোবা, নদী, বালতি বা গোসলের পাত্র","শ্বাস নিচ্ছে না, বা স্বাভাবিকভাবে নিচ্ছে না","অজ্ঞান বা খুব ঝিমিয়ে আছে","পানিতে পড়ার পর কাশি, শ্বাসকষ্ট বা বমি","ত্বক বা ঠোঁট ঠান্ডা, ফ্যাকাশে বা নীল"]},"do_now":{"en":["Get the child out of the water as fast as you can without putting yourself in danger — reach with a stick, bamboo or rope, or throw something that floats, unless you are a trained swimmer.","Shout for help and ask someone to call 999.","Lay the child on their back on a firm surface and check breathing: look, listen and feel for up to 10 seconds.","If they are not breathing and you are trained, give 5 rescue breaths first, then start CPR and keep going until help arrives or they breathe.","If they are breathing, turn them onto their side so water or vomit can drain from the mouth.","Take off wet clothes, dry the child and keep them warm with a dry cloth or blanket.","Take the child to hospital even if they seem completely well — breathing problems can appear hours later."],"bn":["নিজেকে বিপদে না ফেলে যত দ্রুত সম্ভব শিশুকে পানি থেকে তুলুন — প্রশিক্ষিত সাঁতারু না হলে লাঠি, বাঁশ বা দড়ি বাড়িয়ে দিন, বা ভাসে এমন কিছু ছুড়ে দিন।","চিৎকার করে সাহায্য ডাকুন, কাউকে ৯৯৯-এ ফোন করতে বলুন।","শক্ত সমতল জায়গায় চিত করে শুইয়ে শ্বাস দেখুন: ১০ সেকেন্ড পর্যন্ত বুক ওঠানামা দেখুন, শব্দ শুনুন, নিঃশ্বাস অনুভব করুন।","শ্বাস না নিলে আর আপনার প্রশিক্ষণ থাকলে আগে ৫টি কৃত্রিম শ্বাস দিন, তারপর সিপিআর শুরু করুন — সাহায্য না আসা বা শ্বাস না ফেরা পর্যন্ত চালিয়ে যান।","শ্বাস নিলে কাত করে শুইয়ে দিন, যাতে মুখ থেকে পানি বা বমি বেরিয়ে যেতে পারে।","ভেজা কাপড় খুলে শরীর মুছে শুকনো কাপড় বা কাঁথা দিয়ে উষ্ণ রাখুন।","শিশু পুরোপুরি ভালো মনে হলেও হাসপাতালে নিন — শ্বাসের সমস্যা কয়েক ঘণ্টা পরেও দেখা দিতে পারে।"]},"avoid":{"en":["Do not spin the child around, hold them upside down or press on the tummy to get water out — it wastes vital time and can make them breathe in vomit.","Do not jump into deep or fast-moving water unless you are trained — reach or throw instead.","Do not take the child to a traditional healer or wait at home to see how they are.","Do not give food or drink until a doctor has checked them."],"bn":["পানি বের করতে শিশুকে মাথার ওপর ঘোরাবেন না, উল্টো করে ঝোলাবেন না বা পেটে চাপ দেবেন না — এতে জরুরি সময় নষ্ট হয় এবং বমি শ্বাসনালিতে ঢুকে যেতে পারে।","প্রশিক্ষণ না থাকলে গভীর বা স্রোতের পানিতে ঝাঁপ দেবেন না — কিছু বাড়িয়ে দিন বা ছুড়ে দিন।","কবিরাজ বা ওঝার কাছে নেবেন না, বা কেমন থাকে দেখতে বাসায় অপেক্ষা করবেন না।","ডাক্তার না দেখা পর্যন্ত খাবার বা পানীয় দেবেন না।"]},"seek_help":{"en":["Every child taken out of water after struggling needs a hospital check the same day.","Prevention: watch young children every moment near water, fence or cover ponds, ditches and wells, never leave a baby alone in a bath or near a bucket of water, and teach children to swim with trained instructors."],"bn":["পানিতে হাবুডুবু খাওয়ার পর তোলা প্রতিটি শিশুকে সেদিনই হাসপাতালে দেখাতে হবে।","প্রতিরোধ: পানির কাছে ছোট শিশুর ওপর প্রতি মুহূর্তে নজর রাখুন, পুকুর, ডোবা ও কুয়া বেড়া দিয়ে ঘিরুন বা ঢেকে রাখুন, শিশুকে কখনো গোসলের পাত্রে বা পানিভর্তি বালতির কাছে একা রাখবেন না, আর প্রশিক্ষকের কাছে সাঁতার শেখান।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['drowning', 'near-drowning', 'pond', 'water', 'cpr', 'first aid']::text[], false, 'in_review'::lp_review_status, 10203),
  ('fa-burns-scalds', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🔥', '{"en":"Burns and scalds","bn":"পুড়ে যাওয়া ও গরম পানিতে ঝলসানো"}'::jsonb, '{"en":"Cool the burn under cool running water for 20 minutes, cover it loosely with clean cling film or cloth, and never put toothpaste, oil or ice on it.","bn":"পোড়া জায়গা ২০ মিনিট ঠান্ডা চলমান পানির নিচে রাখুন, পরিষ্কার ক্লিং ফিল্ম বা কাপড়ে আলগা করে ঢেকে দিন — টুথপেস্ট, তেল বা বরফ কখনো দেবেন না।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["The burn is larger than the child''s own palm","Burns on the face, hands, feet, private parts or over a joint","Skin looks white, leathery or charred, or a deep burn hurts very little","Burns from electricity or chemicals","Breathed in smoke, or has a cough, hoarse voice or burns around the mouth or nose","Any blistering burn on a baby or young child"],"bn":["পোড়া জায়গা শিশুর নিজের হাতের তালুর চেয়ে বড়","মুখ, হাত, পা, গোপনাঙ্গ বা কোনো জোড়ার ওপর পোড়া","ত্বক সাদা, চামড়ার মতো শক্ত বা কালো হয়ে গেছে, অথবা গভীর পোড়ায় ব্যথা খুব কম","বিদ্যুৎ বা রাসায়নিকে পোড়া","ধোঁয়া টেনেছে, বা কাশি, গলা ভাঙা, মুখ বা নাকের চারপাশে পোড়া","ছোট শিশুর যেকোনো পোড়া, যাতে ফোসকা পড়েছে"]},"do_now":{"en":["Stop the burning: move the child away from the heat. If clothes are on fire, lay the child down and smother the flames with a thick cloth or blanket.","Cool the burn under cool running water for 20 minutes, as soon as possible.","Take off clothing and jewellery near the burn — but not anything stuck to the skin.","Keep the rest of the child warm with a dry cloth so they do not get too cold.","Cover the burn loosely with clean cling film laid along it, or a clean cloth that does not shed fibres.","For pain, give paracetamol as the pack or doctor says by weight.","Go to hospital for any burn in the signs above; call 999 if the child is struggling to breathe."],"bn":["পোড়া থামান: শিশুকে আগুন বা গরম জিনিস থেকে সরিয়ে নিন। কাপড়ে আগুন লাগলে শুইয়ে দিয়ে মোটা কাপড় বা কাঁথা দিয়ে চেপে আগুন নেভান।","যত দ্রুত সম্ভব পোড়া জায়গা ২০ মিনিট ঠান্ডা চলমান পানির নিচে রাখুন।","পোড়ার কাছের কাপড় ও গয়না খুলে ফেলুন — তবে চামড়ায় লেগে যাওয়া কিছু টেনে খুলবেন না।","শিশুর বাকি শরীর শুকনো কাপড়ে ঢেকে উষ্ণ রাখুন, যাতে বেশি ঠান্ডা না হয়ে যায়।","পোড়া জায়গা পরিষ্কার ক্লিং ফিল্ম লম্বালম্বি বিছিয়ে, বা আঁশ ঝরে না এমন পরিষ্কার কাপড়ে আলগা করে ঢেকে দিন।","ব্যথার জন্য প্যাকেটের নির্দেশ বা ডাক্তারের কথামতো ওজন অনুযায়ী প্যারাসিটামল দিন।","ওপরের লক্ষণের যেকোনো পোড়ায় হাসপাতালে যান; শ্বাস নিতে কষ্ট হলে ৯৯৯-এ ফোন করুন।"]},"avoid":{"en":["Do not put toothpaste, oil, ghee, butter, egg, turmeric, honey or any cream on the burn.","Do not use ice or ice-cold water — it can deepen the injury and chill the child.","Do not burst blisters or peel off loose or stuck skin.","Do not wrap the burn tightly or use cotton wool, which sticks to the wound."],"bn":["পোড়ায় টুথপেস্ট, তেল, ঘি, মাখন, ডিম, হলুদ, মধু বা কোনো ক্রিম লাগাবেন না।","বরফ বা বরফ-ঠান্ডা পানি দেবেন না — এতে ক্ষত গভীর হতে পারে, শিশুও ঠান্ডা হয়ে যায়।","ফোসকা গলাবেন না, আলগা বা লেগে থাকা চামড়া টেনে তুলবেন না।","শক্ত করে পেঁচিয়ে বাঁধবেন না, তুলা ব্যবহার করবেন না — তুলা ক্ষতে লেগে যায়।"]},"seek_help":{"en":["Go to hospital for any burn listed in the signs, or whenever you are unsure how deep it is.","See a doctor in the following days if there is more pain, redness, swelling, pus or fever.","Prevention: keep children away from the cooking area and hot pots, turn pan handles inward, and keep kerosene lamps, matches and hot irons out of reach."],"bn":["লক্ষণে উল্লেখ করা যেকোনো পোড়ায়, অথবা পোড়া কতটা গভীর বুঝতে না পারলে হাসপাতালে যান।","পরের দিনগুলোতে ব্যথা বাড়লে, লাল হলে, ফুলে গেলে, পুঁজ হলে বা জ্বর এলে ডাক্তার দেখান।","প্রতিরোধ: রান্নার জায়গা ও গরম হাঁড়ি থেকে শিশুকে দূরে রাখুন, হাঁড়ি-কড়াইয়ের হাতল ভেতরের দিকে ঘুরিয়ে রাখুন, কুপি, ম্যাচ আর গরম ইস্ত্রি নাগালের বাইরে রাখুন।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['burn', 'scald', 'hot water', 'fire', 'first aid']::text[], false, 'in_review'::lp_review_status, 10204),
  ('fa-poisoning', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '☠️', '{"en":"Poisoning — kerosene, medicines, pesticides","bn":"বিষক্রিয়া — কেরোসিন, ওষুধ, কীটনাশক"}'::jsonb, '{"en":"Do not make the child vomit. Go to hospital at once, even if they seem well, and take the bottle, packet or strip with you.","bn":"বমি করানোর চেষ্টা করবেন না। শিশু ভালো মনে হলেও সাথে সাথে হাসপাতালে যান, আর বোতল, প্যাকেট বা ওষুধের পাতা সাথে নিন।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Found with an open bottle, packet, tablets, button battery or plant","Smell of kerosene, pesticide or chemicals on the breath or clothes","Coughing, choking, vomiting or drooling after drinking something","Burns or redness around the mouth","Very sleepy, confused, fitting, or fast or difficult breathing","Small pupils, heavy sweating and drooling (possible pesticide poisoning)"],"bn":["খোলা বোতল, প্যাকেট, ট্যাবলেট, বোতাম ব্যাটারি বা গাছপালা হাতে পাওয়া গেছে","নিঃশ্বাসে বা কাপড়ে কেরোসিন, কীটনাশক বা রাসায়নিকের গন্ধ","কিছু খাওয়ার পর কাশি, দম আটকে আসা, বমি বা মুখ দিয়ে লালা পড়া","মুখের চারপাশে পোড়া বা লালচে ভাব","খুব ঘুম ঘুম, এলোমেলো আচরণ, খিঁচুনি, বা দ্রুত অথবা কষ্টের শ্বাস","চোখের মণি ছোট, প্রচুর ঘাম ও লালা পড়া (কীটনাশকের বিষক্রিয়া হতে পারে)"]},"do_now":{"en":["Take away anything left and wipe or rinse the mouth with water.","If it is on the skin (such as pesticide), take off the clothes and wash the skin well with soap and plenty of water — protect your own hands with gloves or a plastic bag.","If it is in the eyes, rinse them with clean running water for 15 minutes.","Go to hospital at once, even if the child seems well — some poisons act hours later. Call 999 if they are very sleepy, fitting or struggling to breathe.","Take the bottle, packet or medicine strip with you so the doctor knows exactly what it was.","If the child is not responding but is breathing, keep them lying on their side on the way."],"bn":["বাকি যা আছে সরিয়ে নিন, মুখ মুছে দিন বা পানি দিয়ে কুলি করান।","চামড়ায় লাগলে (যেমন কীটনাশক) কাপড় খুলে সাবান ও প্রচুর পানি দিয়ে ভালো করে ধুয়ে দিন — নিজের হাত গ্লাভস বা পলিথিন দিয়ে রক্ষা করুন।","চোখে গেলে ১৫ মিনিট পরিষ্কার চলমান পানি দিয়ে চোখ ধুয়ে দিন।","শিশু ভালো মনে হলেও সাথে সাথে হাসপাতালে যান — কিছু বিষ কয়েক ঘণ্টা পরে কাজ করে। খুব ঘুম ঘুম ভাব, খিঁচুনি বা শ্বাসকষ্ট হলে ৯৯৯-এ ফোন করুন।","বোতল, প্যাকেট বা ওষুধের পাতা সাথে নিন, যাতে ডাক্তার ঠিক কী খেয়েছে জানতে পারেন।","শিশু সাড়া না দিলেও শ্বাস নিলে যাওয়ার পথে কাত করে শুইয়ে রাখুন।"]},"avoid":{"en":["Do not make the child vomit — kerosene and other liquids can get into the lungs, and corrosive chemicals burn a second time on the way up.","Do not give salt water, milk, oil, raw egg or any home remedy.","Do not wait for symptoms to appear.","Do not touch pesticides or soaked clothes with bare hands."],"bn":["বমি করানোর চেষ্টা করবেন না — কেরোসিন ও অন্য তরল ফুসফুসে ঢুকে যেতে পারে, আর ক্ষয়কারী রাসায়নিক উঠে আসার সময় আবার পোড়ায়।","লবণ-পানি, দুধ, তেল, কাঁচা ডিম বা কোনো ঘরোয়া টোটকা দেবেন না।","লক্ষণ দেখা দেওয়ার অপেক্ষায় থাকবেন না।","খালি হাতে কীটনাশক বা ভেজা কাপড় ধরবেন না।"]},"seek_help":{"en":["Every suspected poisoning needs a hospital the same day — especially kerosene, pesticides, iron tablets, adult medicines and button batteries.","Prevention: keep medicines, kerosene, pesticides and cleaners locked away in their original containers — never in water or soft-drink bottles."],"bn":["বিষক্রিয়ার যেকোনো সন্দেহে সেদিনই হাসপাতালে যেতে হবে — বিশেষ করে কেরোসিন, কীটনাশক, আয়রন ট্যাবলেট, বড়দের ওষুধ ও বোতাম ব্যাটারি।","প্রতিরোধ: ওষুধ, কেরোসিন, কীটনাশক ও পরিষ্কারক তালাবদ্ধ করে নিজের আসল পাত্রেই রাখুন — কখনো পানির বা কোমল পানীয়ের বোতলে নয়।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['poisoning', 'kerosene', 'pesticide', 'medicine', 'swallowed', 'first aid']::text[], false, 'in_review'::lp_review_status, 10205),
  ('fa-snakebite', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🐍', '{"en":"Snakebite","bn":"সাপে কামড়"}'::jsonb, '{"en":"Keep the child still, keep the bitten limb still, and go straight to a hospital that gives antivenom. No cutting, sucking, tight bands or ojha.","bn":"শিশুকে স্থির রাখুন, কামড়ানো হাত-পা নড়তে দেবেন না, আর সরাসরি অ্যান্টিভেনম দেওয়া হয় এমন হাসপাতালে যান। কাটা, চোষা, শক্ত বাঁধন বা ওঝা — কোনোটাই নয়।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Any bite where a snake was seen, or two small puncture marks","Swelling or pain spreading up the arm or leg","Drooping eyelids, double vision, or trouble swallowing, speaking or breathing","Bleeding from the gums, nose or bite, or red or dark urine","Sudden belly pain, weakness or drowsiness — especially after sleeping on the floor at night, as krait bites may hardly hurt"],"bn":["সাপ দেখা গেছে এমন যেকোনো কামড়, বা দুটি ছোট ছিদ্রের দাগ","হাত বা পা বেয়ে ফোলা বা ব্যথা ছড়িয়ে পড়ছে","চোখের পাতা ঝুলে পড়া, একটা জিনিস দুটো দেখা, বা গিলতে, কথা বলতে বা শ্বাস নিতে কষ্ট","মাড়ি, নাক বা কামড়ের জায়গা থেকে রক্ত পড়া, বা লাল অথবা কালচে প্রস্রাব","হঠাৎ পেটব্যথা, দুর্বলতা বা ঝিমুনি — বিশেষ করে রাতে মেঝেতে ঘুমানোর পর, কারণ কালাচ (ক্রেইট) সাপের কামড়ে প্রায় ব্যথাই হয় না"]},"do_now":{"en":["Move the child away from the snake. Keep them calm and lying still — movement spreads the venom faster.","Take off rings, bangles, anklets and tight clothes from the bitten limb before it swells.","Keep the bitten limb still with a splint (a stick, bamboo or rolled cardboard tied loosely with cloth), as for a broken bone.","Carry the child or take them lying down by the fastest transport — do not let them walk.","Go straight to the nearest Upazila Health Complex or district hospital, where antivenom can be given; call 999 if needed.","Note the time of the bite. A photo of the snake from a safe distance can help, but do not try to catch or kill it."],"bn":["শিশুকে সাপের কাছ থেকে সরিয়ে নিন। শান্ত রাখুন, শুইয়ে স্থির রাখুন — নড়াচড়ায় বিষ দ্রুত ছড়ায়।","কামড়ানো হাত-পা ফুলে যাওয়ার আগেই আংটি, চুড়ি, নূপুর ও আঁটসাঁট কাপড় খুলে ফেলুন।","ভাঙা হাড়ের মতো করে কামড়ানো হাত বা পা একটা কাঠি, বাঁশ বা মোড়ানো শক্ত কাগজের সাথে কাপড় দিয়ে আলগা করে বেঁধে নড়াচড়া বন্ধ রাখুন।","শিশুকে কোলে করে বা শুইয়ে সবচেয়ে দ্রুত যানবাহনে নিয়ে যান — হাঁটতে দেবেন না।","সরাসরি নিকটস্থ উপজেলা স্বাস্থ্য কমপ্লেক্স বা জেলা হাসপাতালে যান, যেখানে অ্যান্টিভেনম দেওয়া যায়; দরকার হলে ৯৯৯-এ ফোন করুন।","কামড়ের সময়টা মনে রাখুন। নিরাপদ দূরত্ব থেকে সাপের ছবি তুলতে পারলে কাজে লাগে, তবে ধরতে বা মারতে যাবেন না।"]},"avoid":{"en":["Do not cut, suck or burn the bite.","Do not tie a tight band, rope or tourniquet (bandhon) — it can badly damage the limb.","Do not go to an ojha or traditional healer — the time lost can cost a life.","Do not put herbs, chemicals, ice or ''snake stones'' on the bite, and do not give alcohol or any medicine except what the hospital gives."],"bn":["কামড়ের জায়গা কাটবেন না, চুষবেন না বা পোড়াবেন না।","শক্ত করে বাঁধন, দড়ি বা গিঁট দেবেন না — এতে হাত-পায়ের মারাত্মক ক্ষতি হতে পারে।","ওঝা বা কবিরাজের কাছে যাবেন না — নষ্ট হওয়া সময়ে প্রাণ যেতে পারে।","কামড়ের জায়গায় লতাপাতা, রাসায়নিক, বরফ বা ''বিষপাথর'' লাগাবেন না, আর হাসপাতাল যা দেয় তার বাইরে কোনো ওষুধ বা অ্যালকোহল দেবেন না।"]},"seek_help":{"en":["Every snakebite needs a hospital, even if the child seems well — signs of poisoning can take hours to appear.","Prevention: sleep on a raised bed under a well tucked-in mosquito net, use a torch outside at night, and keep the yard clear of rubbish, wood piles and rat holes."],"bn":["প্রতিটি সাপে কামড়ে হাসপাতালে যেতে হবে, শিশু ভালো মনে হলেও — বিষের লক্ষণ দেখা দিতে কয়েক ঘণ্টা লাগতে পারে।","প্রতিরোধ: মেঝেতে নয়, উঁচু খাটে ভালো করে গুঁজে দেওয়া মশারির ভেতরে ঘুমান, রাতে বাইরে টর্চ ব্যবহার করুন, আর উঠান থেকে আবর্জনা, লাকড়ির স্তূপ ও ইঁদুরের গর্ত সরিয়ে রাখুন।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['snakebite', 'snake', 'antivenom', 'rural', 'first aid']::text[], false, 'in_review'::lp_review_status, 10206),
  ('fa-animal-bite-rabies', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🐕', '{"en":"Dog, cat or monkey bite — rabies","bn":"কুকুর, বিড়াল বা বানরের কামড় — জলাতঙ্ক"}'::jsonb, '{"en":"Wash the wound with soap and running water for 15 minutes, then go to a hospital the same day to start the rabies vaccine.","bn":"ক্ষত ১৫ মিনিট সাবান ও চলমান পানি দিয়ে ধুয়ে নিন, তারপর সেদিনই হাসপাতালে গিয়ে জলাতঙ্কের টিকা শুরু করুন।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Any bite or scratch that breaks the skin from a dog, cat, monkey, jackal or mongoose","The animal licked broken skin, a wound, or the eyes, nose or mouth","Bites on the head, face, neck or hands, or deep or many bites (most urgent)","Bleeding that does not stop with pressure"],"bn":["কুকুর, বিড়াল, বানর, শিয়াল বা বেজির কামড় বা আঁচড়, যাতে চামড়া কেটেছে","প্রাণীটি কাটা চামড়া, ক্ষত, বা চোখ, নাক বা মুখ চেটেছে","মাথা, মুখ, ঘাড় বা হাতে কামড়, বা গভীর অথবা অনেকগুলো কামড় (সবচেয়ে জরুরি)","চেপে ধরলেও না থামা রক্তপাত"]},"do_now":{"en":["Wash the wound at once with soap and plenty of running water for 15 minutes — this is one of the most important steps.","Then put on an antiseptic such as povidone-iodine if you have it.","If it is bleeding, press with a clean cloth and cover loosely.","Go to a hospital the same day to start the rabies vaccine — government hospitals give it. The doctor will decide whether rabies immunoglobulin is also needed.","Complete every dose on the dates you are given.","Ask the doctor about tetanus protection too."],"bn":["সাথে সাথে ক্ষত সাবান ও প্রচুর চলমান পানি দিয়ে ১৫ মিনিট ধরে ধুয়ে নিন — এটি সবচেয়ে জরুরি ধাপগুলোর একটি।","তারপর হাতে থাকলে পোভিডোন-আয়োডিনের মতো জীবাণুনাশক লাগান।","রক্ত পড়লে পরিষ্কার কাপড় দিয়ে চেপে ধরুন, আলগা করে ঢেকে দিন।","সেদিনই হাসপাতালে গিয়ে জলাতঙ্কের টিকা শুরু করুন — সরকারি হাসপাতালে দেওয়া হয়। র‍্যাবিস ইমিউনোগ্লোবুলিনও লাগবে কিনা, ডাক্তার ঠিক করবেন।","দেওয়া তারিখ অনুযায়ী প্রতিটি ডোজ সম্পূর্ণ করুন।","ধনুষ্টংকারের সুরক্ষার কথাও ডাক্তারকে জিজ্ঞেস করুন।"]},"avoid":{"en":["Do not put chilli, lime, turmeric, mustard oil, soil, ash or any paste on the wound.","Do not have the wound stitched or tightly bandaged before a doctor sees it.","Do not go to an ojha or rely on herbal treatment — once rabies symptoms start, it is almost always fatal.","Do not wait to see whether the animal falls sick before starting the vaccine."],"bn":["ক্ষতে মরিচ, চুন, হলুদ, সরিষার তেল, মাটি, ছাই বা কোনো প্রলেপ লাগাবেন না।","ডাক্তার দেখার আগে ক্ষত সেলাই করাবেন না বা শক্ত করে ব্যান্ডেজ বাঁধবেন না।","ওঝার কাছে যাবেন না বা লতাপাতার চিকিৎসার ওপর ভরসা করবেন না — জলাতঙ্কের লক্ষণ একবার শুরু হলে প্রায় সবসময়ই মৃত্যু ঘটে।","প্রাণীটি অসুস্থ হয় কিনা দেখার জন্য টিকা শুরু করতে দেরি করবেন না।"]},"seek_help":{"en":["Every bite or scratch from these animals needs a doctor the same day, even if it is small.","Teach children not to tease or touch stray dogs, cats or monkeys, and to tell an adult at once about any bite or scratch."],"bn":["এসব প্রাণীর যেকোনো কামড় বা আঁচড়ে, ছোট হলেও, সেদিনই ডাক্তার দেখাতে হবে।","শিশুদের শেখান রাস্তার কুকুর, বিড়াল বা বানরকে যেন উত্যক্ত না করে বা না ছোঁয়, আর কামড় বা আঁচড় লাগলে সাথে সাথে বড় কাউকে জানায়।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['dog bite', 'cat bite', 'monkey bite', 'rabies', 'vaccine', 'first aid']::text[], false, 'in_review'::lp_review_status, 10207),
  ('fa-head-injury', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🤕', '{"en":"Head injury — warning signs","bn":"মাথায় আঘাত — বিপদের লক্ষণ"}'::jsonb, '{"en":"Most bumps on the head are minor, but these signs mean the child needs a hospital now. Watch closely for 24–48 hours after any knock.","bn":"মাথায় বেশিরভাগ আঘাত সামান্য, কিন্তু এই লক্ষণগুলো থাকলে এখনই হাসপাতালে নিতে হবে। যেকোনো আঘাতের পর ২৪–৪৮ ঘণ্টা ভালো করে খেয়াল রাখুন।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Lost consciousness, even for a moment","Vomiting more than once","Very sleepy, hard to wake, confused or behaving strangely","A fit (convulsion)","Severe or worsening headache","Blood or clear fluid from the nose or ears, or bruising behind the ears or around the eyes","Weakness, or trouble walking, speaking or seeing","A baby under 1 year with a swelling or bruise on the head","A fall from a height such as a roof, tree or stairs, or a road accident"],"bn":["অল্প সময়ের জন্য হলেও জ্ঞান হারিয়েছে","একবারের বেশি বমি","খুব ঘুম ঘুম, জাগাতে কষ্ট, এলোমেলো কথা বা অস্বাভাবিক আচরণ","খিঁচুনি","তীব্র বা বাড়তে থাকা মাথাব্যথা","নাক বা কান দিয়ে রক্ত বা পানির মতো তরল, অথবা কানের পেছনে বা চোখের চারপাশে কালশিটে","দুর্বলতা, বা হাঁটতে, কথা বলতে বা দেখতে সমস্যা","১ বছরের কম শিশুর মাথায় ফোলা বা কালশিটে","ছাদ, গাছ বা সিঁড়ির মতো উঁচু জায়গা থেকে পড়া, বা সড়ক দুর্ঘটনা"]},"do_now":{"en":["If the child is not responding, call 999. Do not move the neck unless they are in danger; if they are breathing, keep the head and neck in line.","If they are awake, let them rest and hold a cold, damp cloth or a cold pack wrapped in cloth on the bump for 10–20 minutes.","Stay with them and watch closely for any warning sign over the next 24–48 hours.","They may sleep if they want to, but check on them often and make sure they wake up normally.","For pain, give paracetamol as the pack or doctor says by weight.","Go to hospital at once if any warning sign appears."],"bn":["শিশু সাড়া না দিলে ৯৯৯-এ ফোন করুন। বিপদ না থাকলে ঘাড় নাড়াবেন না; শ্বাস নিলে মাথা ও ঘাড় সোজা এক রেখায় রাখুন।","জেগে থাকলে বিশ্রাম নিতে দিন, আর ফোলা জায়গায় ১০–২০ মিনিট ঠান্ডা ভেজা কাপড় বা কাপড়ে মোড়ানো ঠান্ডা কিছু ধরে রাখুন।","পাশে থাকুন, পরের ২৪–৪৮ ঘণ্টা বিপদের কোনো লক্ষণ দেখা দেয় কিনা ভালো করে খেয়াল রাখুন।","ঘুমাতে চাইলে ঘুমাতে দিন, তবে বারবার দেখুন এবং নিশ্চিত হোন যে স্বাভাবিকভাবে জেগে উঠছে।","ব্যথার জন্য প্যাকেটের নির্দেশ বা ডাক্তারের কথামতো ওজন অনুযায়ী প্যারাসিটামল দিন।","বিপদের কোনো লক্ষণ দেখা দিলে সাথে সাথে হাসপাতালে যান।"]},"avoid":{"en":["Do not massage the head or rub oil on the swelling.","Do not leave the child alone for the first 24 hours.","Do not give sleeping medicine or strong painkillers that can hide warning signs.","Do not let them go back to sport or rough play until a doctor says it is safe, if they had any warning sign."],"bn":["মাথা মালিশ করবেন না বা ফোলায় তেল ঘষবেন না।","প্রথম ২৪ ঘণ্টা শিশুকে একা রাখবেন না।","ঘুমের ওষুধ বা কড়া ব্যথানাশক দেবেন না — এতে বিপদের লক্ষণ ঢাকা পড়ে যেতে পারে।","বিপদের কোনো লক্ষণ থেকে থাকলে ডাক্তার নিরাপদ না বলা পর্যন্ত খেলাধুলা বা হুটোপুটিতে ফিরতে দেবেন না।"]},"seek_help":{"en":["Go to hospital if any warning sign appears, even a day or two after the injury.","Prevention: helmets on bicycles and motorbikes, safe seating for children in vehicles, and rails on roofs, balconies and stairs."],"bn":["আঘাতের এক-দুই দিন পরেও বিপদের কোনো লক্ষণ দেখা দিলে হাসপাতালে যান।","প্রতিরোধ: সাইকেল ও মোটরসাইকেলে হেলমেট, গাড়িতে শিশুর নিরাপদ বসার ব্যবস্থা, আর ছাদ, বারান্দা ও সিঁড়িতে রেলিং।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['head injury', 'fall', 'concussion', 'bump', 'first aid']::text[], false, 'in_review'::lp_review_status, 10208),
  ('fa-febrile-seizure', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🌡️', '{"en":"Fits with fever (febrile seizure)","bn":"জ্বরের সাথে খিঁচুনি"}'::jsonb, '{"en":"Lay the child on their side, time the fit and keep them safe. Call 999 if it lasts more than 5 minutes, and see a doctor the same day.","bn":"শিশুকে কাত করে শুইয়ে দিন, খিঁচুনির সময় দেখুন, নিরাপদে রাখুন। ৫ মিনিটের বেশি চললে ৯৯৯-এ ফোন করুন, আর সেদিনই ডাক্তার দেখান।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["High fever, then the body suddenly goes stiff and the arms and legs jerk","Eyes rolling up, not responding","Lips may turn blue; the child may wet themselves","Usually stops by itself within a few minutes","Emergency: it lasts more than 5 minutes, or another fit follows"],"bn":["তীব্র জ্বরের মধ্যে হঠাৎ শরীর শক্ত হয়ে যায়, হাত-পা ঝাঁকুনি দেয়","চোখ ওপরে উল্টে যায়, সাড়া দেয় না","ঠোঁট নীল হতে পারে; প্রস্রাব হয়ে যেতে পারে","সাধারণত কয়েক মিনিটের মধ্যে নিজে থেকেই থেমে যায়","জরুরি: ৫ মিনিটের বেশি চললে, বা আবার খিঁচুনি হলে"]},"do_now":{"en":["Stay calm and note the time the fit starts.","Lay the child on their side on a soft, flat place such as a bed or the floor, away from anything hard or sharp.","Loosen tight clothes and take off extra layers.","Stay with them until the fit stops.","Call 999 or go to hospital at once if it lasts more than 5 minutes.","When it stops, keep them on their side and check they are breathing normally. Being very sleepy afterwards is normal.","Take the child to a doctor the same day, especially after a first fit, to find the cause of the fever.","Once fully awake, give fluids, and paracetamol as the pack or doctor says by weight for comfort."],"bn":["শান্ত থাকুন, খিঁচুনি কখন শুরু হলো সময়টা দেখে রাখুন।","শিশুকে বিছানা বা মেঝের মতো নরম সমতল জায়গায় কাত করে শোয়ান, শক্ত বা ধারালো জিনিস থেকে দূরে।","আঁটসাঁট কাপড় ঢিলা করুন, বাড়তি কাপড় খুলে দিন।","খিঁচুনি না থামা পর্যন্ত পাশে থাকুন।","৫ মিনিটের বেশি চললে সাথে সাথে ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।","থেমে গেলে কাত করেই রাখুন, স্বাভাবিকভাবে শ্বাস নিচ্ছে কিনা দেখুন। পরে খুব ঘুম ঘুম ভাব স্বাভাবিক।","জ্বরের কারণ খুঁজতে সেদিনই ডাক্তার দেখান, বিশেষ করে প্রথমবার খিঁচুনি হলে।","পুরোপুরি জেগে উঠলে পানীয় দিন, আর আরামের জন্য প্যাকেটের নির্দেশ বা ডাক্তারের কথামতো ওজন অনুযায়ী প্যারাসিটামল দিন।"]},"avoid":{"en":["Do not put anything in the mouth — not a spoon, finger or cloth. The child will not swallow their tongue.","Do not hold them down or try to stop the jerking.","Do not pour water on them, put them in a cold bath, or make them smell a shoe or onion.","Do not give anything to eat or drink until they are fully awake. Fever medicine makes a child more comfortable but does not prevent fits."],"bn":["মুখে কিছু দেবেন না — চামচ, আঙুল বা কাপড়ও নয়। শিশু জিভ গিলে ফেলবে না।","চেপে ধরে রাখবেন না বা ঝাঁকুনি থামানোর চেষ্টা করবেন না।","গায়ে পানি ঢালবেন না, ঠান্ডা পানিতে বসাবেন না, জুতা বা পেঁয়াজ শোঁকাবেন না।","পুরোপুরি জেগে না ওঠা পর্যন্ত কিছু খেতে বা পান করতে দেবেন না। জ্বরের ওষুধে শিশু আরাম পায়, কিন্তু তা খিঁচুনি ঠেকায় না।"]},"seek_help":{"en":["Call 999 or go to hospital if the fit lasts more than 5 minutes, another fit follows, the child has trouble breathing, does not wake properly within an hour, or has a stiff neck, a rash or seems very ill.","Every first fit needs a doctor''s check, and so does any fit in a baby under 6 months.","Most children who have fits with fever grow out of them without lasting harm."],"bn":["খিঁচুনি ৫ মিনিটের বেশি চললে, আবার খিঁচুনি হলে, শ্বাসকষ্ট হলে, এক ঘণ্টার মধ্যে ঠিকমতো না জাগলে, বা ঘাড় শক্ত, র‍্যাশ বা খুব অসুস্থ মনে হলে ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।","প্রথমবারের খিঁচুনিতে, আর ৬ মাসের কম শিশুর যেকোনো খিঁচুনিতে ডাক্তার দেখাতেই হবে।","জ্বরে খিঁচুনি হওয়া বেশিরভাগ শিশু বড় হলে এটা কাটিয়ে ওঠে, কোনো স্থায়ী ক্ষতি হয় না।"]}}'::jsonb, 2, 183, 2192, '{}'::text[], 'any', ARRAY['febrile seizure', 'fit', 'convulsion', 'fever', 'first aid']::text[], false, 'in_review'::lp_review_status, 10209),
  ('fa-dengue-warning-signs', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🦟', '{"en":"Dengue — warning signs","bn":"ডেঙ্গু — বিপদের লক্ষণ"}'::jsonb, '{"en":"The danger time is often when the fever goes down. Severe belly pain, repeated vomiting, bleeding or a very tired, restless child means hospital now. Plenty of fluids; paracetamol only.","bn":"বিপদের সময় প্রায়ই জ্বর কমে আসার সময়টা। তীব্র পেটব্যথা, বারবার বমি, রক্তপাত, বা শিশু খুব নিস্তেজ বা অস্থির হলে এখনই হাসপাতালে। প্রচুর তরল খাবার দিন; শুধু প্যারাসিটামল।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Severe or constant belly pain","Vomiting again and again","Bleeding from the gums or nose, blood in vomit or stool, or black stool","Very tired, drowsy, restless or irritable","Cold, clammy hands and feet","Passing little or no urine for 4–6 hours","Fast or difficult breathing","These signs often appear around day 3–7, just as the fever falls — a falling fever does not mean the danger is over"],"bn":["তীব্র বা একটানা পেটব্যথা","বারবার বমি","মাড়ি বা নাক দিয়ে রক্ত, বমি বা পায়খানায় রক্ত, বা কালো পায়খানা","খুব নিস্তেজ, ঘুম ঘুম, অস্থির বা খিটখিটে","হাত-পা ঠান্ডা ও ভেজা ভেজা","৪–৬ ঘণ্টা ধরে প্রস্রাব খুব কম বা একেবারে নেই","দ্রুত বা কষ্টের শ্বাস","এই লক্ষণগুলো প্রায়ই ৩য় থেকে ৭ম দিনের দিকে, ঠিক জ্বর কমার সময় দেখা দেয় — জ্বর কমা মানেই বিপদ কেটে যাওয়া নয়"]},"do_now":{"en":["Go to hospital at once if any warning sign appears.","Give plenty of fluids through the day — ORS, water, soup, coconut water, fruit juice or milk; keep breastfeeding babies often.","Let the child rest.","For fever, give paracetamol only, as the pack or doctor says by weight, and sponge with lukewarm water.","Keep track of how often the child passes urine.","During dengue season, see a doctor in the first days of any fever and do blood tests as they advise.","Keep the sick child under a mosquito net, even in the daytime, so mosquitoes do not spread the infection to others."],"bn":["বিপদের যেকোনো লক্ষণ দেখা দিলে সাথে সাথে হাসপাতালে যান।","সারাদিন প্রচুর তরল দিন — খাবার স্যালাইন, পানি, স্যুপ, ডাবের পানি, ফলের রস বা দুধ; বুকের দুধ খাওয়া শিশুকে ঘন ঘন খাওয়ান।","শিশুকে বিশ্রাম নিতে দিন।","জ্বরের জন্য শুধু প্যারাসিটামল দিন, প্যাকেটের নির্দেশ বা ডাক্তারের কথামতো ওজন অনুযায়ী, আর কুসুম গরম পানিতে গা মুছে দিন।","শিশু কতবার প্রস্রাব করছে তা খেয়াল রাখুন।","ডেঙ্গুর মৌসুমে যেকোনো জ্বরের প্রথম দিনগুলোতেই ডাক্তার দেখান, আর তাঁর পরামর্শমতো রক্ত পরীক্ষা করান।","অসুস্থ শিশুকে দিনের বেলাতেও মশারির ভেতরে রাখুন, যাতে মশা অন্যদের মধ্যে সংক্রমণ ছড়াতে না পারে।"]},"avoid":{"en":["Do not give aspirin, ibuprofen or similar painkillers — they raise the risk of bleeding.","Do not give injections or medicines a doctor has not prescribed.","Do not rely on papaya-leaf juice or other home remedies instead of hospital care.","Do not cut down fluids because the fever has gone."],"bn":["অ্যাসপিরিন, আইবুপ্রোফেন বা এ ধরনের ব্যথানাশক দেবেন না — এতে রক্তপাতের ঝুঁকি বাড়ে।","ডাক্তার দেননি এমন ইনজেকশন বা ওষুধ দেবেন না।","হাসপাতালের চিকিৎসার বদলে পেঁপে পাতার রস বা অন্য ঘরোয়া টোটকার ওপর ভরসা করবেন না।","জ্বর চলে গেছে বলে তরল খাওয়ানো কমাবেন না।"]},"seek_help":{"en":["Any fever during the dengue season — especially during and after the monsoon — is worth a doctor''s check.","Prevention: every week, empty standing water around the home — flower tubs, tyres, coconut shells, buckets, fridge and AC trays. Aedes mosquitoes breed in clean water and bite in the daytime."],"bn":["ডেঙ্গুর মৌসুমে — বিশেষ করে বর্ষার সময় ও পরে — যেকোনো জ্বরে ডাক্তার দেখানো ভালো।","প্রতিরোধ: প্রতি সপ্তাহে বাড়ির আশেপাশে জমে থাকা পানি ফেলে দিন — ফুলের টব, টায়ার, ডাবের খোসা, বালতি, ফ্রিজ ও এসির ট্রে। এডিস মশা পরিষ্কার পানিতে ডিম পাড়ে আর দিনের বেলা কামড়ায়।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['dengue', 'fever', 'mosquito', 'bleeding', 'monsoon', 'first aid']::text[], false, 'in_review'::lp_review_status, 10210),
  ('fa-severe-dehydration', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '💧', '{"en":"Severe dehydration","bn":"মারাত্মক পানিশূন্যতা"}'::jsonb, '{"en":"A very sleepy child with sunken eyes who cannot drink needs a hospital now. Give ORS in small sips on the way and keep breastfeeding.","bn":"খুব নিস্তেজ, চোখ বসে যাওয়া, পান করতে না পারা শিশুকে এখনই হাসপাতালে নিতে হবে। পথে অল্প অল্প করে খাবার স্যালাইন দিন, বুকের দুধ চালিয়ে যান।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Very sleepy, floppy or hard to wake","Not able to drink, or drinking very poorly","Sunken eyes","A pinch of skin on the tummy goes back very slowly","Very little or no urine for many hours, no tears, very dry mouth","A sunken soft spot on the head in a baby"],"bn":["খুব নিস্তেজ, নেতিয়ে পড়া বা জাগাতে কষ্ট","পান করতে পারছে না, বা খুব কম পান করছে","চোখ বসে গেছে","পেটের চামড়া চিমটি দিয়ে ছাড়লে খুব ধীরে আগের অবস্থায় ফেরে","অনেক ঘণ্টা ধরে প্রস্রাব খুব কম বা নেই, চোখে পানি নেই, মুখ খুব শুকনো","শিশুর মাথার তালু (নরম জায়গা) বসে গেছে"]},"do_now":{"en":["Go to hospital now — severe dehydration usually needs fluids through a drip.","On the way, if the child can drink, give ORS in small, frequent sips from a cup or spoon.","Keep breastfeeding often.","Make ORS exactly as the packet says with safe water, and throw it away after the time printed on the packet.","If the child vomits, wait 10 minutes, then give ORS more slowly.","After treatment, give zinc for as many days as your health worker advises, and keep feeding."],"bn":["এখনই হাসপাতালে যান — মারাত্মক পানিশূন্যতায় সাধারণত শিরায় স্যালাইন লাগে।","পথে শিশু পান করতে পারলে কাপ বা চামচে অল্প অল্প করে ঘন ঘন খাবার স্যালাইন দিন।","ঘন ঘন বুকের দুধ খাওয়াতে থাকুন।","প্যাকেটে যেভাবে লেখা ঠিক সেভাবে নিরাপদ পানিতে খাবার স্যালাইন বানান, আর প্যাকেটে লেখা সময় পার হলে ফেলে দিন।","বমি করলে ১০ মিনিট অপেক্ষা করে আবার আরও ধীরে স্যালাইন দিন।","চিকিৎসার পর স্বাস্থ্যকর্মী যতদিন বলেন ততদিন জিংক দিন, আর খাওয়ানো চালিয়ে যান।"]},"avoid":{"en":["Do not stop breastfeeding or food.","Do not give soft drinks, glucose water, sweet juice, or ORS made stronger than the packet says.","Do not give medicines to stop diarrhoea unless a doctor prescribes them.","Do not wait at home if the child cannot drink or is very sleepy."],"bn":["বুকের দুধ বা খাবার বন্ধ করবেন না।","কোমল পানীয়, গ্লুকোজ-পানি, মিষ্টি জুস, বা প্যাকেটের চেয়ে ঘন করে বানানো স্যালাইন দেবেন না।","ডাক্তার না দিলে পাতলা পায়খানা বন্ধের ওষুধ দেবেন না।","শিশু পান করতে না পারলে বা খুব নিস্তেজ হলে বাসায় অপেক্ষা করবেন না।"]},"seek_help":{"en":["Also go to a health facility the same day if the child is restless and very thirsty, has blood in the stool, a high fever, or diarrhoea lasting more than 14 days.","Babies under 6 months and children who are very thin or malnourished lose water faster — get help early."],"bn":["শিশু অস্থির ও খুব তৃষ্ণার্ত হলে, পায়খানায় রক্ত গেলে, বেশি জ্বর থাকলে, বা ১৪ দিনের বেশি ডায়রিয়া চললে সেদিনই স্বাস্থ্যকেন্দ্রে যান।","৬ মাসের কম শিশু আর খুব রোগা বা অপুষ্ট শিশুর শরীর থেকে পানি দ্রুত কমে — আগেভাগে সাহায্য নিন।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['dehydration', 'diarrhoea', 'vomiting', 'ors', 'zinc', 'first aid']::text[], false, 'in_review'::lp_review_status, 10211),
  ('fa-electric-shock', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '⚡', '{"en":"Electric shock","bn":"বিদ্যুৎস্পৃষ্ট হওয়া"}'::jsonb, '{"en":"Switch off the power before you touch the child. Check breathing, cool any burns, and always go to hospital.","bn":"শিশুকে ছোঁয়ার আগে বিদ্যুৎ বন্ধ করুন। শ্বাস দেখুন, পোড়া থাকলে ঠান্ডা পানি দিন, আর সবসময় হাসপাতালে নিন।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["Touched a live wire, socket or appliance, or is found next to one","Unconscious or not breathing","Burns where the current went in and came out","Confused, fitting, or complaining of chest pain","Numbness, muscle pain or trouble breathing","Any shock from overhead lines or high-voltage cables"],"bn":["বিদ্যুতের তার, সকেট বা যন্ত্র ছুঁয়েছে, বা তার পাশে পড়ে আছে","অজ্ঞান বা শ্বাস নিচ্ছে না","বিদ্যুৎ যেখান দিয়ে ঢুকেছে ও বেরিয়েছে সেখানে পোড়া","এলোমেলো আচরণ, খিঁচুনি, বা বুকে ব্যথার কথা বলছে","অবশ ভাব, মাংসপেশিতে ব্যথা বা শ্বাসকষ্ট","মাথার ওপরের লাইন বা উচ্চ ভোল্টেজের তার থেকে যেকোনো শক"]},"do_now":{"en":["Do not touch the child while they may still be in contact with the electricity.","Switch off the power at the main switch, or unplug the appliance.","If you cannot switch it off, stand on something dry (wood, a rubber mat, thick newspaper) and push the source away with a dry wooden stick, broom handle or plastic chair.","For fallen power lines or high-voltage cables, stay well back and call 999 and the electricity office — do not go near.","Once it is safe, check breathing. If the child is not breathing, call 999 and start CPR if you are trained; if breathing but not responding, lay them on their side.","Cool any burns under running water for 20 minutes and cover loosely with clean cling film or cloth.","Take the child to hospital even if they seem fine — electricity can injure the heart and the inside of the body."],"bn":["শিশু বিদ্যুতের সংস্পর্শে থাকতে পারে এমন অবস্থায় তাকে ছোঁবেন না।","মেইন সুইচ বন্ধ করুন, বা যন্ত্রের প্লাগ খুলে ফেলুন।","বন্ধ করতে না পারলে শুকনো কিছুর ওপর দাঁড়ান (কাঠ, রাবারের ম্যাট, মোটা খবরের কাগজ), তারপর শুকনো কাঠের লাঠি, ঝাড়ুর হাতল বা প্লাস্টিকের চেয়ার দিয়ে বিদ্যুতের উৎস ঠেলে সরিয়ে দিন।","ছিঁড়ে পড়া বিদ্যুতের লাইন বা উচ্চ ভোল্টেজের তারের ক্ষেত্রে দূরে থাকুন, ৯৯৯ ও বিদ্যুৎ অফিসে ফোন করুন — কাছে যাবেন না।","নিরাপদ হলে শ্বাস দেখুন। শ্বাস না নিলে ৯৯৯-এ ফোন করুন, প্রশিক্ষণ থাকলে সিপিআর শুরু করুন; শ্বাস নিলেও সাড়া না দিলে কাত করে শোয়ান।","পোড়া থাকলে ২০ মিনিট চলমান পানির নিচে রাখুন, তারপর পরিষ্কার ক্লিং ফিল্ম বা কাপড়ে আলগা করে ঢেকে দিন।","শিশু ভালো মনে হলেও হাসপাতালে নিন — বিদ্যুৎ হৃৎপিণ্ড ও শরীরের ভেতরের ক্ষতি করতে পারে।"]},"avoid":{"en":["Do not touch the child with bare hands, or with anything wet or metal, until the power is off.","Do not step into water that may be touching a live wire, such as a flooded room or street in the monsoon.","Do not throw water on an electrical fire.","Do not put oil, toothpaste or ice on electrical burns."],"bn":["বিদ্যুৎ বন্ধ না হওয়া পর্যন্ত খালি হাতে, বা ভেজা অথবা ধাতব কিছু দিয়ে শিশুকে ছোঁবেন না।","বিদ্যুতের তারের সংস্পর্শে থাকতে পারে এমন পানিতে পা দেবেন না — যেমন বর্ষায় পানি ওঠা ঘর বা রাস্তা।","বিদ্যুতের আগুনে পানি ঢালবেন না।","বিদ্যুতে পোড়ায় তেল, টুথপেস্ট বা বরফ লাগাবেন না।"]},"seek_help":{"en":["Every electric shock needs a hospital check, even if the child seems well.","Prevention: cover sockets, repair loose or broken wires, keep chargers and irons out of reach, and keep children away from rooftop wires and flood water."],"bn":["যেকোনো বিদ্যুৎস্পৃষ্ট হওয়ার পর শিশু ভালো মনে হলেও হাসপাতালে দেখাতে হবে।","প্রতিরোধ: সকেট ঢেকে রাখুন, আলগা বা ছেঁড়া তার মেরামত করুন, চার্জার ও ইস্ত্রি নাগালের বাইরে রাখুন, আর ছাদের তার ও বন্যার পানি থেকে শিশুকে দূরে রাখুন।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['electric shock', 'electricity', 'socket', 'wire', 'burn', 'first aid']::text[], false, 'in_review'::lp_review_status, 10212),
  ('fa-broken-bone-fall', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🦴', '{"en":"Broken bone or serious fall","bn":"হাড় ভাঙা বা গুরুতরভাবে পড়ে যাওয়া"}'::jsonb, '{"en":"Keep the injured part still as you found it, support it, and go to hospital. Do not straighten it and do not go to a traditional bone-setter.","bn":"আঘাতের জায়গা যেমন আছে তেমনই স্থির রাখুন, ঠেকনা দিন, আর হাসপাতালে যান। সোজা করার চেষ্টা করবেন না, হাড়-জোড়া দেওয়া কবিরাজের কাছে যাবেন না।"}'::jsonb, '{}'::jsonb, '{"signs":{"en":["A fall from a height — a roof, tree, stairs, balcony or moving vehicle","Severe pain, swelling or bruising, or a limb that looks bent or out of shape","Cannot move the limb or put weight on it","Bone showing through the skin, or heavy bleeding","Neck or back pain, numbness or tingling, or weakness in the arms or legs","Unconscious, drowsy or vomiting after the fall"],"bn":["উঁচু জায়গা থেকে পড়া — ছাদ, গাছ, সিঁড়ি, বারান্দা বা চলন্ত গাড়ি","তীব্র ব্যথা, ফোলা বা কালশিটে, বা হাত-পা বাঁকা অথবা বেঢপ দেখাচ্ছে","হাত-পা নাড়াতে পারছে না বা ভর দিতে পারছে না","চামড়া ফুঁড়ে হাড় দেখা যাচ্ছে, বা অনেক রক্তপাত","ঘাড় বা পিঠে ব্যথা, অবশ বা ঝিনঝিন ভাব, বা হাত-পায়ে দুর্বলতা","পড়ে যাওয়ার পর অজ্ঞান, ঝিমুনি বা বমি"]},"do_now":{"en":["If you think the neck or back is hurt, do not move the child unless they are in danger. Keep the head and neck still and call 999.","Stop bleeding by pressing around the wound with a clean cloth — not on a bone that sticks out — and cover it.","Keep the injured limb still in the position you found it. Support it with padding, a folded newspaper, cardboard or a pillow tied loosely with cloth; use a sling for an arm.","Hold a cold pack wrapped in cloth on the area for up to 20 minutes to ease swelling.","For pain, give paracetamol as the pack or doctor says by weight.","Take the child to hospital for an X-ray; carry them if a leg is hurt."],"bn":["ঘাড় বা পিঠে আঘাত লেগেছে মনে হলে বিপদ না থাকলে শিশুকে নাড়াবেন না। মাথা ও ঘাড় স্থির রাখুন, ৯৯৯-এ ফোন করুন।","পরিষ্কার কাপড় দিয়ে ক্ষতের চারপাশে চেপে রক্তপাত থামান — বেরিয়ে থাকা হাড়ের ওপর চাপ দেবেন না — তারপর ঢেকে দিন।","আঘাত পাওয়া হাত-পা যে অবস্থায় পেয়েছেন সেভাবেই স্থির রাখুন। নরম কিছু, ভাঁজ করা খবরের কাগজ, শক্ত কাগজ বা বালিশ দিয়ে ঠেকনা দিয়ে কাপড়ে আলগা করে বাঁধুন; হাতের জন্য গলায় ঝুলিয়ে স্লিং দিন।","ফোলা কমাতে কাপড়ে মোড়ানো ঠান্ডা কিছু ২০ মিনিট পর্যন্ত ধরে রাখুন।","ব্যথার জন্য প্যাকেটের নির্দেশ বা ডাক্তারের কথামতো ওজন অনুযায়ী প্যারাসিটামল দিন।","এক্স-রের জন্য হাসপাতালে নিন; পায়ে আঘাত হলে কোলে করে নিন।"]},"avoid":{"en":["Do not try to straighten or push back a bent limb or bone.","Do not go to a traditional bone-setter — tight bamboo splints and binding can cut off the blood supply and cause permanent damage.","Do not massage the injury or rub oil on it.","Do not give food or drink until a doctor has seen the child, in case an operation is needed."],"bn":["বাঁকা হাত-পা বা হাড় সোজা করার বা ঠেলে বসানোর চেষ্টা করবেন না।","হাড়-জোড়া দেওয়া কবিরাজের কাছে যাবেন না — শক্ত বাঁশের চটা আর আঁটসাঁট বাঁধনে রক্ত চলাচল বন্ধ হয়ে স্থায়ী ক্ষতি হতে পারে।","আঘাতের জায়গা মালিশ করবেন না বা তেল ঘষবেন না।","অপারেশন লাগতে পারে, তাই ডাক্তার না দেখা পর্যন্ত খাবার বা পানীয় দেবেন না।"]},"seek_help":{"en":["Go to hospital urgently if fingers or toes beyond the injury turn pale, blue, cold or numb, or if the pain gets much worse after splinting.","Prevention: rails on roofs, balconies and stairs, window guards, and never letting children ride on the roof or footboard of a bus."],"bn":["আঘাতের পরের দিকের আঙুল ফ্যাকাশে, নীল, ঠান্ডা বা অবশ হয়ে গেলে, বা ঠেকনা দেওয়ার পর ব্যথা অনেক বেড়ে গেলে জরুরি ভিত্তিতে হাসপাতালে যান।","প্রতিরোধ: ছাদ, বারান্দা ও সিঁড়িতে রেলিং, জানালায় গ্রিল, আর শিশুকে কখনো বাসের ছাদে বা পাদানিতে চড়তে না দেওয়া।"]}}'::jsonb, 2, 0, NULL, '{}'::text[], 'any', ARRAY['broken bone', 'fracture', 'fall', 'splint', 'first aid']::text[], false, 'in_review'::lp_review_status, 10213)
