INSERT INTO lp_milestones (key, kind, area, title, description, how_to_support, typical_day, emoji, source_key, review_status, sort_order) VALUES
  ('ms_y6_has_friends', 'development', 'social_emotional', '{"en":"Has a friend or two and plays cooperatively","bn":"এক-দুজন বন্ধু আছে, মিলেমিশে খেলে"}'::jsonb, '{"en":"Most children by this age enjoy playing with other children, can share and take turns, and have one or two special friends. Quarrels still happen and are usually over quickly.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু অন্য শিশুদের সাথে খেলতে ভালোবাসে, ভাগাভাগি করতে ও পালা মেনে চলতে পারে, আর এক-দুজন প্রিয় বন্ধু থাকে। ঝগড়া এখনো হয়, তবে সাধারণত তাড়াতাড়ি মিটে যায়।"}'::jsonb, '{"en":"Invite a classmate or cousin over to play. When there is a fight, help them say what the problem is and find a fair solution, instead of solving it for them.","bn":"সহপাঠী বা চাচাতো-মামাতো ভাইবোনকে বাসায় খেলতে ডাকুন। ঝগড়া হলে নিজে মিটিয়ে না দিয়ে সমস্যাটা কী তা বলতে আর ন্যায্য সমাধান খুঁজতে সাহায্য করুন।"}'::jsonb, 2192, '👫', 'aap_healthychildren', 'in_review'::lp_review_status, 10001),
  ('ms_y6_reads_simple_words', 'development', 'learning', '{"en":"Recognises letters and reads some simple words","bn":"অক্ষর চেনে, কিছু সহজ শব্দ পড়তে পারে"}'::jsonb, '{"en":"Most children by this age know most letters of the alphabet they are learning, can write their own name and are starting to read short, simple words. A child learning two or three scripts at once (Bangla, English, Arabic) may take a little longer in each, and that is normal.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু যে বর্ণমালা শিখছে তার বেশিরভাগ অক্ষর চেনে, নিজের নাম লিখতে পারে, আর ছোট সহজ শব্দ পড়তে শুরু করে। যে শিশু একসাথে বাংলা, ইংরেজি ও আরবি — দুই-তিনটি লিপি শিখছে, তার প্রতিটিতে একটু বেশি সময় লাগতে পারে; এটা স্বাভাবিক।"}'::jsonb, '{"en":"Read with your child every day and point to the words as you read. Play letter-hunting games with signboards and packets. Keep it fun — pressure and long handwriting drills at this age often backfire.","bn":"প্রতিদিন সন্তানের সাথে পড়ুন, পড়ার সময় আঙুল দিয়ে শব্দ দেখান। সাইনবোর্ড বা প্যাকেটের লেখা থেকে অক্ষর খোঁজার খেলা খেলুন। আনন্দের মধ্যে রাখুন — এই বয়সে চাপ দিয়ে বা লম্বা সময় হাতের লেখা করালে প্রায়ই উল্টো ফল হয়।"}'::jsonb, 2192, '🔤', 'aap_healthychildren', 'in_review'::lp_review_status, 10002),
  ('ms_y6_balance_skills', 'development', 'movement', '{"en":"Hops, skips, balances well and can learn to ride a bicycle","bn":"লাফায়, ভারসাম্য রাখে, সাইকেল চালানো শিখতে পারে"}'::jsonb, '{"en":"Most children by this age can hop, skip, climb and stand on one foot for a while. Many can learn to ride a bicycle with training wheels or with an adult holding on.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু এক পায়ে লাফাতে, লাফিয়ে লাফিয়ে দৌড়াতে, বেয়ে উঠতে এবং কিছুক্ষণ এক পায়ে দাঁড়াতে পারে। অনেকে পাশের সাপোর্ট চাকা লাগিয়ে বা বড় কেউ ধরে রাখলে সাইকেল চালানো শিখে ফেলে।"}'::jsonb, '{"en":"Make time every day for running games, climbing and ball play outdoors. For cycling, use a helmet and choose safe places away from traffic, ponds and ditches.","bn":"প্রতিদিন বাইরে দৌড়ঝাঁপ, বেয়ে ওঠা আর বল খেলার সময় রাখুন। সাইকেল চালানোর সময় হেলমেট পরান, আর রাস্তা, পুকুর ও খাল-ডোবা থেকে দূরে নিরাপদ জায়গা বেছে নিন।"}'::jsonb, 2192, '🚲', 'aap_healthychildren', 'in_review'::lp_review_status, 10003),
  ('ms_y6_dresses_self', 'development', 'self_care', '{"en":"Dresses, washes and uses the toilet on their own","bn":"নিজে জামা পরে, হাত-মুখ ধোয়, একা টয়লেট ব্যবহার করে"}'::jsonb, '{"en":"Most children by this age can put on most of their clothes, wash their hands and face, and use the toilet without help, including washing afterwards. Small buttons and laces may still need help.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু বেশিরভাগ জামাকাপড় নিজে পরতে, হাত-মুখ ধুতে এবং সাহায্য ছাড়া টয়লেট ব্যবহার করতে পারে — পরে পানি দিয়ে পরিষ্কার হওয়াসহ। ছোট বোতাম বা জুতার ফিতায় এখনো সাহায্য লাগতে পারে।"}'::jsonb, '{"en":"Leave enough time in the morning so they can do it themselves. Praise the effort, not only the result, and teach handwashing with soap before meals and after the toilet.","bn":"সকালে হাতে একটু বেশি সময় রাখুন, যাতে নিজে করতে পারে। শুধু ফলাফল নয়, চেষ্টারও প্রশংসা করুন, আর খাওয়ার আগে ও টয়লেটের পরে সাবান দিয়ে হাত ধোয়া শেখান।"}'::jsonb, 2192, '👕', 'aap_healthychildren', 'in_review'::lp_review_status, 10004),
  ('ms_y6_understands_time', 'development', 'cognitive', '{"en":"Understands simple time words and counts objects","bn":"সময়ের সহজ কথা বোঝে, জিনিস গুনতে পারে"}'::jsonb, '{"en":"Most children by this age understand words like yesterday, today and tomorrow, know morning from evening, and can count a small group of objects correctly.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু গতকাল, আজ, আগামীকাল বোঝে, সকাল আর সন্ধ্যার পার্থক্য জানে, এবং ছোট একদল জিনিস ঠিকভাবে গুনতে পারে।"}'::jsonb, '{"en":"Talk about the day''s plan in order: ''first school, then lunch, then play''. Count things together — stairs, mangoes, plates on the table.","bn":"দিনের পরিকল্পনা ক্রম ধরে বলুন: ''আগে স্কুল, তারপর দুপুরের খাবার, তারপর খেলা''। একসাথে জিনিস গুনুন — সিঁড়ি, আম, টেবিলের প্লেট।"}'::jsonb, 2192, '📅', 'aap_healthychildren', 'in_review'::lp_review_status, 10005),
  ('ms_y7_follows_game_rules', 'development', 'social_emotional', '{"en":"Follows the rules of a game and copes better with losing","bn":"খেলার নিয়ম মানে, হারলেও আগের চেয়ে ভালো সামলে নেয়"}'::jsonb, '{"en":"Most children by this age can play games with rules, wait for their turn and accept that someone else wins, though losing can still bring tears sometimes.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু নিয়ম মেনে খেলতে, নিজের পালার জন্য অপেক্ষা করতে এবং অন্য কেউ জিতলে মেনে নিতে পারে — যদিও হেরে গেলে মাঝে মাঝে এখনো কান্না আসে।"}'::jsonb, '{"en":"Play ludo, carrom or board games as a family. Show how you lose gracefully yourself, and talk about the feeling: ''It is hard to lose. What could we try next time?''","bn":"পরিবারের সবাই মিলে লুডু, ক্যারাম বা বোর্ড গেম খেলুন। নিজে হেরে কীভাবে হাসিমুখে মেনে নিতে হয় তা দেখান, আর অনুভূতি নিয়ে কথা বলুন: ''হারলে খারাপ লাগে। পরেরবার কী চেষ্টা করা যায়?''"}'::jsonb, 2557, '🎲', 'aap_healthychildren', 'in_review'::lp_review_status, 10006),
  ('ms_y7_tells_events', 'development', 'language', '{"en":"Tells events in order and enjoys jokes and riddles","bn":"ঘটনা ক্রম অনুযায়ী বলে, ধাঁধা ও মজার কথা উপভোগ করে"}'::jsonb, '{"en":"Most children by this age can tell you what happened at school in the right order, ask and answer ''why'' and ''how'' questions, and enjoy simple jokes and riddles.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু স্কুলে কী হয়েছে তা ঠিক ক্রমে বলতে পারে, ''কেন'' আর ''কীভাবে'' প্রশ্ন করে ও উত্তর দেয়, আর সহজ কৌতুক ও ধাঁধা উপভোগ করে।"}'::jsonb, '{"en":"Ask open questions at mealtimes: ''What was the funniest thing today?'' Listen to the whole answer without correcting every word. Share riddles from your own childhood.","bn":"খাওয়ার সময় খোলা প্রশ্ন করুন: ''আজ সবচেয়ে মজার কী হলো?'' প্রতিটি শব্দ শুধরে না দিয়ে পুরো উত্তর শুনুন। নিজের ছোটবেলার ধাঁধা শোনান।"}'::jsonb, 2557, '🗨️', 'aap_healthychildren', 'in_review'::lp_review_status, 10007),
  ('ms_y7_simple_sums', 'development', 'cognitive', '{"en":"Adds and takes away small numbers","bn":"ছোট সংখ্যা যোগ-বিয়োগ করতে পারে"}'::jsonb, '{"en":"Most children by this age can add and subtract small numbers, often using fingers or objects, and are beginning to understand money, the days of the week and the months.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু আঙুল বা জিনিস দিয়ে ছোট সংখ্যা যোগ-বিয়োগ করতে পারে, আর টাকা, সপ্তাহের দিন ও মাসের ধারণা বুঝতে শুরু করে।"}'::jsonb, '{"en":"Use real life: count the change at the shop, share sweets equally, look at the calendar together. If numbers seem much harder for your child than for classmates, talk to the teacher.","bn":"বাস্তব জীবনে কাজে লাগান: দোকানে ফেরত টাকা গোনা, মিষ্টি সমান ভাগ করা, একসাথে ক্যালেন্ডার দেখা। সহপাঠীদের তুলনায় সংখ্যা অনেক বেশি কঠিন মনে হলে শিক্ষকের সাথে কথা বলুন।"}'::jsonb, 2557, '➕', 'aap_healthychildren', 'in_review'::lp_review_status, 10008),
  ('ms_y7_daily_routine', 'development', 'self_care', '{"en":"Follows a simple daily routine with reminders","bn":"মনে করিয়ে দিলে দৈনন্দিন রুটিন মেনে চলে"}'::jsonb, '{"en":"Most children by this age can brush their teeth, get dressed, pack their school bag and get ready for bed with a few reminders.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু একটু মনে করিয়ে দিলে দাঁত ব্রাশ, জামা পরা, স্কুলব্যাগ গোছানো আর ঘুমের প্রস্তুতি নিজেই করতে পারে।"}'::jsonb, '{"en":"Make a picture chart of the morning and bedtime steps. Keep the same order every day and praise each step they manage alone.","bn":"সকাল ও ঘুমের আগের কাজগুলোর একটা ছবির তালিকা বানান। প্রতিদিন একই ক্রম রাখুন, আর কোনো ধাপ একা পারলে প্রশংসা করুন।"}'::jsonb, 2557, '⏰', 'aap_healthychildren', 'in_review'::lp_review_status, 10009),
  ('ms_y8_talks_feelings', 'development', 'social_emotional', '{"en":"Names their feelings and understands how others feel","bn":"নিজের অনুভূতির নাম বলে, অন্যের অনুভূতিও বোঝে"}'::jsonb, '{"en":"Most children by this age can say when they feel angry, worried, embarrassed or proud, and can imagine how a friend might feel. Big feelings can still spill over, especially when they are tired or hungry.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু রাগ, দুশ্চিন্তা, লজ্জা বা গর্ব হলে তা বলতে পারে, আর বন্ধুর কেমন লাগছে তা কল্পনা করতে পারে। তবে ক্লান্ত বা ক্ষুধার্ত থাকলে বড় আবেগ এখনো সামলাতে কষ্ট হয়।"}'::jsonb, '{"en":"Name feelings out loud, including your own. When they are upset, listen first and solve later. A quiet corner or a short walk together can help them calm down.","bn":"অনুভূতির নাম মুখে বলুন, নিজেরটাও। মন খারাপ হলে আগে শুনুন, সমাধান পরে। একটা শান্ত কোণ বা একসাথে একটু হাঁটা শান্ত হতে সাহায্য করে।"}'::jsonb, 2922, '💭', 'aap_healthychildren', 'in_review'::lp_review_status, 10010),
  ('ms_y8_explains_clearly', 'development', 'language', '{"en":"Explains in full sentences how something works","bn":"পূর্ণ বাক্যে কোনো কিছু কীভাবে চলে তা বুঝিয়ে বলে"}'::jsonb, '{"en":"Most children by this age speak in clear, full sentences, can explain the rules of a game or how something works, and understand most of what adults say to them.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু স্পষ্ট পূর্ণ বাক্যে কথা বলে, কোনো খেলার নিয়ম বা কোনো কিছু কীভাবে চলে তা বুঝিয়ে বলতে পারে, আর বড়দের বেশিরভাগ কথা বোঝে।"}'::jsonb, '{"en":"Ask them to teach you something — a game, or a fact from school. If their speech is hard to understand or they struggle to follow instructions, ask a doctor about a hearing and speech check.","bn":"সন্তানকে বলুন আপনাকে কিছু শেখাতে — একটা খেলা বা স্কুলে শেখা কোনো তথ্য। কথা বোঝা কঠিন হলে বা নির্দেশ মানতে কষ্ট হলে শ্রবণ ও কথা বলার পরীক্ষা নিয়ে ডাক্তারকে জিজ্ঞেস করুন।"}'::jsonb, 2922, '🗣️', 'aap_healthychildren', 'in_review'::lp_review_status, 10011),
  ('ms_y8_solves_problems', 'development', 'cognitive', '{"en":"Solves simple problems step by step","bn":"ধাপে ধাপে সহজ সমস্যার সমাধান করে"}'::jsonb, '{"en":"Most children by this age can think through a simple problem, try another way when the first one fails, and sort and compare things by more than one feature.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু সহজ সমস্যা নিয়ে ভাবতে পারে, প্রথম উপায়ে না হলে অন্য উপায়ে চেষ্টা করে, আর একাধিক বৈশিষ্ট্য দেখে জিনিস সাজাতে ও তুলনা করতে পারে।"}'::jsonb, '{"en":"Offer puzzles, building toys and small jobs that need some planning. When they are stuck, ask ''What else could you try?'' instead of giving the answer.","bn":"ধাঁধা, বানানোর খেলনা আর একটু পরিকল্পনা লাগে এমন ছোট কাজ দিন। আটকে গেলে উত্তর বলে না দিয়ে জিজ্ঞেস করুন, ''আর কী চেষ্টা করা যায়?''"}'::jsonb, 2922, '🧩', 'aap_healthychildren', 'in_review'::lp_review_status, 10012),
  ('ms_y8_good_coordination', 'development', 'movement', '{"en":"Runs, throws and catches with good control","bn":"দৌড়ানো, ছোড়া ও ধরায় ভালো নিয়ন্ত্রণ"}'::jsonb, '{"en":"Most children by this age run, jump, climb, throw and catch with good control, and can learn sports and swimming with proper teaching.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু ভালো নিয়ন্ত্রণ নিয়ে দৌড়ায়, লাফায়, বেয়ে ওঠে, বল ছোড়ে ও ধরে, আর ঠিকভাবে শেখালে খেলাধুলা ও সাঁতার শিখতে পারে।"}'::jsonb, '{"en":"Let them try different games — football, cricket, skipping, kabaddi. If they cannot swim yet, arrange lessons with a trained adult in a safe place; in Bangladesh, swimming is a life-saving skill.","bn":"নানা রকম খেলা চেষ্টা করতে দিন — ফুটবল, ক্রিকেট, দড়িলাফ, কাবাডি। এখনো সাঁতার না জানলে নিরাপদ জায়গায় প্রশিক্ষিত কারো কাছে শেখার ব্যবস্থা করুন; বাংলাদেশে সাঁতার জীবন বাঁচানোর দক্ষতা।"}'::jsonb, 2922, '🏊', 'aap_healthychildren', 'in_review'::lp_review_status, 10013),
  ('ms_y10_belongs_group', 'development', 'social_emotional', '{"en":"Friendships matter more; wants to fit in with a group","bn":"বন্ধুত্ব বেশি গুরুত্বপূর্ণ হয়ে ওঠে; দলের অংশ হতে চায়"}'::jsonb, '{"en":"Most children by this age have closer friendships, care about what friends think and want to belong. They may compare themselves with others and become more sensitive to teasing.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশুর বন্ধুত্ব আরও গভীর হয়, বন্ধুরা কী ভাবছে তা নিয়ে চিন্তা করে এবং দলে জায়গা পেতে চায়। অন্যদের সাথে নিজেকে তুলনা করতে পারে, আর খোঁচা বা ঠাট্টায় বেশি কষ্ট পায়।"}'::jsonb, '{"en":"Get to know their friends and the friends'' families. Ask about their day without judging. Watch for signs of bullying — not wanting to go to school, lost belongings, sadness without a clear reason.","bn":"সন্তানের বন্ধু ও তাদের পরিবারের সাথে পরিচিত হোন। বিচার না করে দিনের কথা জিজ্ঞেস করুন। বুলিংয়ের লক্ষণ খেয়াল রাখুন — স্কুলে যেতে না চাওয়া, জিনিস হারানো, কারণ ছাড়া মন খারাপ।"}'::jsonb, 3652, '🧑‍🤝‍🧑', 'aap_healthychildren', 'in_review'::lp_review_status, 10014),
  ('ms_y10_reads_to_learn', 'development', 'learning', '{"en":"Reads to learn and writes a few paragraphs","bn":"শেখার জন্য পড়ে, কয়েক অনুচ্ছেদ লিখতে পারে"}'::jsonb, '{"en":"Most children by this age read fluently enough to learn new things from books, can find information, and write a few connected paragraphs about a topic.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু এতটা সাবলীলভাবে পড়ে যে বই থেকে নতুন কিছু শিখতে পারে, তথ্য খুঁজে বের করতে পারে, আর একটা বিষয়ে কয়েকটি গোছানো অনুচ্ছেদ লিখতে পারে।"}'::jsonb, '{"en":"Keep storybooks and children''s magazines at home, not only textbooks. If reading is still slow and effortful, or letters get mixed up a lot, talk to the teacher — some children need extra help, and there is nothing shameful in that.","bn":"শুধু পাঠ্যবই নয়, বাসায় গল্পের বই ও শিশুদের পত্রিকা রাখুন। পড়া এখনো খুব ধীর ও কষ্টের হলে, বা অক্ষর বারবার গুলিয়ে ফেললে শিক্ষকের সাথে কথা বলুন — কিছু শিশুর বাড়তি সাহায্য লাগে, এতে লজ্জার কিছু নেই।"}'::jsonb, 3652, '📖', 'aap_healthychildren', 'in_review'::lp_review_status, 10015),
  ('ms_y10_plans_tasks', 'development', 'cognitive', '{"en":"Plans and finishes small tasks with less help","bn":"কম সাহায্যে ছোট কাজ পরিকল্পনা করে শেষ করে"}'::jsonb, '{"en":"Most children by this age can plan simple steps, remember their homework and stay with a task for longer, though they still need adults to help with bigger projects and deadlines.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু সহজ ধাপ পরিকল্পনা করতে, বাড়ির কাজ মনে রাখতে এবং বেশিক্ষণ মন দিয়ে কাজ করতে পারে — তবে বড় কাজ ও সময়সীমার জন্য এখনো বড়দের সাহায্য লাগে।"}'::jsonb, '{"en":"Help them break a big task into small steps and write them down. Let them choose the order. Check in, but let them do the work.","bn":"বড় কাজকে ছোট ছোট ধাপে ভাগ করে লিখে ফেলতে সাহায্য করুন। কোনটা আগে করবে, সে-ই ঠিক করুক। খোঁজ নিন, কিন্তু কাজটা তাকেই করতে দিন।"}'::jsonb, 3652, '🗂️', 'aap_healthychildren', 'in_review'::lp_review_status, 10016),
  ('ms_y10_household_jobs', 'development', 'self_care', '{"en":"Does regular jobs at home and looks after own things","bn":"বাসায় নিয়মিত কাজ করে, নিজের জিনিস গুছিয়ে রাখে"}'::jsonb, '{"en":"Most children by this age can do regular household jobs — making the bed, folding clothes, setting the table, watering plants — and keep track of their own belongings.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু ঘরের নিয়মিত কাজ করতে পারে — বিছানা গোছানো, কাপড় ভাঁজ করা, খাবার টেবিল সাজানো, গাছে পানি দেওয়া — আর নিজের জিনিসপত্রের খেয়াল রাখতে পারে।"}'::jsonb, '{"en":"Give sons and daughters the same kinds of jobs. A father doing housework in front of the children teaches more than any lecture.","bn":"ছেলে ও মেয়ে দুজনকেই একই ধরনের কাজ দিন। বাবা সন্তানের সামনে ঘরের কাজ করলে তা যেকোনো উপদেশের চেয়ে বেশি শেখায়।"}'::jsonb, 3652, '🧹', 'aap_healthychildren', 'in_review'::lp_review_status, 10017),
  ('ms_y12_wants_privacy', 'development', 'social_emotional', '{"en":"Wants more privacy and independence","bn":"আরও বেশি একান্ত সময় ও স্বাধীনতা চায়"}'::jsonb, '{"en":"Most children by this age want more privacy, more say in their own choices and more time with friends. Moods can change quickly as puberty begins.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু আরও বেশি গোপনীয়তা, নিজের সিদ্ধান্তে বেশি মত দেওয়ার সুযোগ আর বন্ধুদের সাথে বেশি সময় চায়। বয়ঃসন্ধি শুরু হওয়ায় মেজাজ দ্রুত বদলাতে পারে।"}'::jsonb, '{"en":"Knock before entering their room, and give choices within clear family rules. Stay close in small ways — the trip to school, a snack together, a few minutes at bedtime.","bn":"ঘরে ঢোকার আগে দরজায় টোকা দিন, আর পরিবারের স্পষ্ট নিয়মের ভেতরে পছন্দের সুযোগ দিন। ছোট ছোট উপায়ে কাছে থাকুন — স্কুলে আসা-যাওয়ার পথে, একসাথে নাশতায়, ঘুমের আগে কয়েক মিনিট।"}'::jsonb, 4383, '🚪', 'aap_healthychildren', 'in_review'::lp_review_status, 10018),
  ('ms_y12_shares_opinion', 'development', 'language', '{"en":"Explains and defends their own opinion","bn":"নিজের মত বুঝিয়ে বলে, যুক্তি দেয়"}'::jsonb, '{"en":"Most children by this age can give reasons for their views, argue a point (sometimes loudly), and understand sarcasm and double meanings.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু নিজের মতের পেছনে যুক্তি দিতে পারে, তর্ক করতে পারে (কখনো জোর গলায়), আর ব্যঙ্গ ও দ্বৈত অর্থ বোঝে।"}'::jsonb, '{"en":"As long as they stay polite, treat arguments as practice in thinking, not as disrespect. Ask ''Why do you think that?'' and really listen. Show them how to disagree kindly.","bn":"ভদ্রতা বজায় থাকলে তর্ককে বেয়াদবি না ভেবে চিন্তা করার অনুশীলন হিসেবে দেখুন। জিজ্ঞেস করুন, ''তুমি এমন কেন ভাবছ?'' — এবং মন দিয়ে শুনুন। কীভাবে নরমভাবে দ্বিমত করতে হয়, নিজে করে দেখান।"}'::jsonb, 4383, '💬', 'aap_healthychildren', 'in_review'::lp_review_status, 10019),
  ('ms_y12_abstract_thinking', 'development', 'cognitive', '{"en":"Thinks about ideas like fairness and ''what if''","bn":"ন্যায়-অন্যায় ও ''যদি এমন হতো'' ধরনের ভাবনা ভাবে"}'::jsonb, '{"en":"Most children by this age are starting to think beyond what they can see — about fairness, right and wrong, the future and other people''s points of view.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু চোখে দেখা জিনিসের বাইরেও ভাবতে শুরু করে — ন্যায়-অন্যায়, ঠিক-ভুল, ভবিষ্যৎ আর অন্যের দৃষ্টিভঙ্গি নিয়ে।"}'::jsonb, '{"en":"Discuss news, stories and everyday dilemmas together. Share your family''s values and the reasons behind them, and welcome their questions — including questions about faith.","bn":"খবর, গল্প আর দৈনন্দিন দ্বিধা নিয়ে একসাথে আলোচনা করুন। পরিবারের মূল্যবোধ ও তার পেছনের কারণ বলুন, আর তাদের প্রশ্নকে স্বাগত জানান — ধর্ম নিয়ে প্রশ্নও।"}'::jsonb, 4383, '🤔', 'aap_healthychildren', 'in_review'::lp_review_status, 10020),
  ('ms_y12_own_hygiene', 'development', 'self_care', '{"en":"Takes care of own hygiene as the body changes","bn":"শরীর বদলানোর সাথে নিজের পরিচ্ছন্নতার যত্ন নেয়"}'::jsonb, '{"en":"Most children by this age can bathe, wash their hair, trim their nails and keep their clothes clean by themselves. As puberty starts they need guidance on sweat, body odour and, for girls, managing periods.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু নিজে গোসল, চুল ধোয়া, নখ কাটা ও কাপড় পরিষ্কার রাখতে পারে। বয়ঃসন্ধি শুরু হলে ঘাম, শরীরের গন্ধ এবং মেয়েদের মাসিক সামলানো নিয়ে দিকনির্দেশনা দরকার।"}'::jsonb, '{"en":"Talk about body changes before they happen — mothers and fathers can both do this. Keep pads, soap and a private place to change ready, and answer questions calmly.","bn":"শরীরের পরিবর্তন শুরু হওয়ার আগেই কথা বলুন — মা-বাবা দুজনেই পারেন। প্যাড, সাবান আর কাপড় বদলানোর একান্ত জায়গা প্রস্তুত রাখুন, আর প্রশ্নের উত্তর শান্তভাবে দিন।"}'::jsonb, 4383, '🧼', 'aap_healthychildren', 'in_review'::lp_review_status, 10021),
  ('ms_y12_homework_habits', 'development', 'learning', '{"en":"Manages homework and exam study with some guidance","bn":"কিছুটা দিকনির্দেশনায় বাড়ির কাজ ও পরীক্ষার পড়া সামলায়"}'::jsonb, '{"en":"Most children by this age can do their homework on their own, prepare for tests with a plan, and ask for help when they do not understand.","bn":"এই বয়সের মধ্যে বেশিরভাগ শিশু নিজে বাড়ির কাজ করতে, পরিকল্পনা করে পরীক্ষার প্রস্তুতি নিতে এবং না বুঝলে সাহায্য চাইতে পারে।"}'::jsonb, '{"en":"Agree on a regular study time and a quiet place with no phone nearby. Praise effort and steady habits more than marks.","bn":"পড়ার একটা নির্দিষ্ট সময় আর ফোন ছাড়া শান্ত জায়গা ঠিক করুন। নম্বরের চেয়ে চেষ্টা আর নিয়মিত অভ্যাসের প্রশংসা বেশি করুন।"}'::jsonb, 4383, '📝', 'aap_healthychildren', 'in_review'::lp_review_status, 10022),
  ('ms_y14_peer_influence', 'development', 'social_emotional', '{"en":"Friends'' opinions matter a lot, but family still matters","bn":"বন্ধুদের মতামত খুব গুরুত্বপূর্ণ, তবু পরিবার এখনো জরুরি"}'::jsonb, '{"en":"Most teenagers by this age care deeply about what friends think and may follow the group in clothes, language and online life. They still need closeness with their family — and quietly value it.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী বন্ধুরা কী ভাবছে তা নিয়ে খুব চিন্তা করে, আর পোশাক, কথা বলার ধরন ও অনলাইন জীবনে দলকে অনুসরণ করতে পারে। তবু পরিবারের কাছাকাছি থাকা তাদের দরকার — মুখে না বললেও তারা তা মূল্য দেয়।"}'::jsonb, '{"en":"Keep talking, especially side by side — in a rickshaw, while cooking, on a walk. Agree on rules for going out and for phones together, and explain your reasons.","bn":"কথা চালিয়ে যান, বিশেষ করে পাশাপাশি থেকে — রিকশায়, রান্নার সময়, হাঁটতে হাঁটতে। বাইরে যাওয়া ও ফোনের নিয়ম একসাথে ঠিক করুন, আর কারণ ব্যাখ্যা করুন।"}'::jsonb, 5114, '👥', 'aap_healthychildren', 'in_review'::lp_review_status, 10023),
  ('ms_y14_identity', 'development', 'cognitive', '{"en":"Explores who they are — values, interests and beliefs","bn":"নিজেকে খোঁজে — মূল্যবোধ, আগ্রহ ও বিশ্বাস"}'::jsonb, '{"en":"Most teenagers by this age are working out who they are: what they believe, what they are good at and what they want. They may question rules and ideas they once accepted.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী নিজেকে বোঝার চেষ্টা করে: কী বিশ্বাস করে, কীসে ভালো, কী চায়। আগে মেনে নেওয়া নিয়ম ও ধারণা নিয়ে প্রশ্ন তুলতে পারে।"}'::jsonb, '{"en":"Encourage hobbies, clubs, volunteering and sport where they can discover their strengths. Answer hard questions honestly; if you do not know, find out together.","bn":"শখ, ক্লাব, স্বেচ্ছাসেবা ও খেলাধুলায় উৎসাহ দিন, যেখানে নিজের শক্তির জায়গা আবিষ্কার করতে পারে। কঠিন প্রশ্নের সৎ উত্তর দিন; না জানলে একসাথে খুঁজে বের করুন।"}'::jsonb, 5114, '🪞', 'aap_healthychildren', 'in_review'::lp_review_status, 10024),
  ('ms_y14_growth_spurt', 'development', 'movement', '{"en":"Going through a growth spurt","bn":"দ্রুত লম্বা হওয়ার সময় চলছে"}'::jsonb, '{"en":"Most girls by this age have had or are in their main growth spurt, and many boys are in the middle of theirs. During a spurt teenagers need more food and sleep and may feel clumsy for a while.","bn":"এই বয়সের মধ্যে বেশিরভাগ মেয়ের দ্রুত লম্বা হওয়ার প্রধান সময়টা পার হয়েছে বা চলছে; অনেক ছেলের এটা এখন চলছে। এ সময় খাবার ও ঘুম বেশি লাগে, আর কিছুদিন হাত-পা একটু বেসামাল লাগতে পারে।"}'::jsonb, '{"en":"Offer filling, healthy food — rice with dal, fish, eggs, vegetables, milk — and keep sport going. Protect sleep by keeping phones out of the bedroom at night.","bn":"পেট ভরানো স্বাস্থ্যকর খাবার দিন — ভাত-ডাল, মাছ, ডিম, শাকসবজি, দুধ — আর খেলাধুলা চালিয়ে যেতে দিন। রাতে ফোন শোবার ঘরের বাইরে রেখে ঘুম রক্ষা করুন।"}'::jsonb, 5114, '📏', 'aap_healthychildren', 'in_review'::lp_review_status, 10025),
  ('ms_y14_study_planning', 'development', 'learning', '{"en":"Plans own study time with less reminding","bn":"কম মনে করিয়ে দিলেও নিজের পড়ার সময় পরিকল্পনা করে"}'::jsonb, '{"en":"Most teenagers by this age can make a study timetable, keep track of assignments and balance study with rest, though phones and stress can easily get in the way.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী পড়ার রুটিন বানাতে, অ্যাসাইনমেন্টের খেয়াল রাখতে এবং পড়া ও বিশ্রামের ভারসাম্য রাখতে পারে — যদিও ফোন আর মানসিক চাপ সহজেই বাধা হয়ে দাঁড়ায়।"}'::jsonb, '{"en":"Help them make a weekly plan once, then step back. Notice signs of too much pressure — poor sleep, headaches, not eating — and remind them that their worth is not measured in marks.","bn":"একবার সাপ্তাহিক পরিকল্পনা বানাতে সাহায্য করুন, তারপর পিছিয়ে আসুন। অতিরিক্ত চাপের লক্ষণ খেয়াল করুন — ঘুম কম, মাথাব্যথা, না খাওয়া — আর মনে করিয়ে দিন, নম্বর দিয়ে তার মূল্য মাপা যায় না।"}'::jsonb, 5114, '🗓️', 'aap_healthychildren', 'in_review'::lp_review_status, 10026),
  ('ms_y16_handles_conflict', 'development', 'social_emotional', '{"en":"Handles strong feelings and disagreements better","bn":"তীব্র আবেগ ও মতবিরোধ আগের চেয়ে ভালো সামলায়"}'::jsonb, '{"en":"Most teenagers by this age are better at calming down, seeing both sides and sorting out arguments with friends and family, though stress can still bring outbursts.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী নিজেকে শান্ত করতে, দুই পক্ষের দিক দেখতে আর বন্ধু ও পরিবারের সাথে মতবিরোধ মেটাতে আগের চেয়ে বেশি পারে — যদিও চাপে এখনো হঠাৎ রাগ ফেটে পড়তে পারে।"}'::jsonb, '{"en":"Stay calm when they are not, and come back to the problem later. If you notice lasting sadness, pulling away from everyone or talk of self-harm, get help from a doctor or counsellor early.","bn":"সে শান্ত না থাকলেও আপনি শান্ত থাকুন, পরে বিষয়টিতে ফিরে আসুন। দীর্ঘদিনের মন খারাপ, সবার কাছ থেকে গুটিয়ে যাওয়া বা নিজের ক্ষতি করার কথা শুনলে দেরি না করে ডাক্তার বা কাউন্সেলরের সাহায্য নিন।"}'::jsonb, 5844, '🤝', 'aap_healthychildren', 'in_review'::lp_review_status, 10027),
  ('ms_y16_weighs_risks', 'development', 'cognitive', '{"en":"Can weigh risks and consequences — but not always with friends","bn":"ঝুঁকি ও পরিণতি বিচার করতে পারে — তবে বন্ধুদের সাথে সবসময় নয়"}'::jsonb, '{"en":"Most teenagers by this age can think through risks and long-term consequences when they are calm. With friends or in an exciting moment, impulsive choices are still common; the brain keeps maturing into the twenties.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী শান্ত অবস্থায় ঝুঁকি ও দীর্ঘমেয়াদি পরিণতি বিচার করতে পারে। কিন্তু বন্ধুদের সাথে বা উত্তেজনার মুহূর্তে হুটহাট সিদ্ধান্ত এখনো সাধারণ; মস্তিষ্কের পরিপক্বতা বিশের কোঠা পর্যন্ত চলতে থাকে।"}'::jsonb, '{"en":"Talk through real situations before they happen — a motorbike ride, a dare, an online request for photos. Promise that they can always call you to be picked up, with no questions asked in the moment.","bn":"পরিস্থিতি আসার আগেই কথা বলে রাখুন — মোটরসাইকেলে চড়া, সাহস দেখানোর চ্যালেঞ্জ, অনলাইনে ছবি চাওয়া। কথা দিন যে যেকোনো সময় ফোন করলে আপনি নিতে আসবেন, তখনই কোনো প্রশ্ন না করে।"}'::jsonb, 5844, '⚖️', 'aap_healthychildren', 'in_review'::lp_review_status, 10028),
  ('ms_y16_study_choices', 'development', 'learning', '{"en":"Thinks about study streams and future work","bn":"পড়ার বিভাগ ও ভবিষ্যৎ পেশা নিয়ে ভাবে"}'::jsonb, '{"en":"Most teenagers by this age are facing big exams such as the SSC and starting to think about study streams, college, technical training and future work.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী এসএসসির মতো বড় পরীক্ষার মুখোমুখি হয় এবং বিভাগ, কলেজ, কারিগরি প্রশিক্ষণ ও ভবিষ্যৎ পেশা নিয়ে ভাবতে শুরু করে।"}'::jsonb, '{"en":"Explore the options together — let them talk to relatives and neighbours who do different jobs. Respect their interests and abilities, even if they differ from your hopes.","bn":"একসাথে বিকল্পগুলো খুঁজে দেখুন — বিভিন্ন পেশার আত্মীয় ও প্রতিবেশীর সাথে কথা বলার সুযোগ করে দিন। আপনার আশার সাথে না মিললেও তার আগ্রহ ও সামর্থ্যকে সম্মান করুন।"}'::jsonb, 5844, '🎓', 'aap_healthychildren', 'in_review'::lp_review_status, 10029),
  ('ms_y16_everyday_skills', 'development', 'self_care', '{"en":"Manages everyday life skills","bn":"দৈনন্দিন জীবনের দক্ষতা সামলায়"}'::jsonb, '{"en":"Most teenagers by this age can cook a simple meal, manage pocket money, travel safely on public transport and run a small errand on their own.","bn":"এই বয়সের মধ্যে বেশিরভাগ কিশোর-কিশোরী সহজ রান্না করতে, হাতখরচ সামলাতে, গণপরিবহনে নিরাপদে চলাচল করতে এবং ছোটখাটো কাজ একা সারতে পারে।"}'::jsonb, '{"en":"Teach one new skill each month — cooking rice and dal, paying a bill, using mobile banking safely, basic first aid. Teach sons and daughters the same skills.","bn":"প্রতি মাসে একটা নতুন দক্ষতা শেখান — ভাত-ডাল রান্না, বিল দেওয়া, নিরাপদে মোবাইল ব্যাংকিং, প্রাথমিক চিকিৎসা। ছেলে-মেয়ে দুজনকেই একই দক্ষতা শেখান।"}'::jsonb, 5844, '🍳', 'aap_healthychildren', 'in_review'::lp_review_status, 10030),
  ('ms_y18_adult_relationship', 'development', 'social_emotional', '{"en":"Builds a more adult relationship with parents","bn":"মা-বাবার সাথে আরও পরিণত সম্পর্ক গড়ে"}'::jsonb, '{"en":"Most young people by this age relate to their parents more as adults — sharing views, asking for advice rather than permission, and showing care for the family in their own way.","bn":"এই বয়সের মধ্যে বেশিরভাগ তরুণ-তরুণী মা-বাবার সাথে আরও পরিণত মানুষের মতো সম্পর্ক রাখে — মত বিনিময় করে, অনুমতির বদলে পরামর্শ চায়, আর নিজের মতো করে পরিবারের প্রতি যত্ন দেখায়।"}'::jsonb, '{"en":"Move from directing to advising. Include them in family decisions and ask their opinion; respect grows best when it is shown in both directions.","bn":"নির্দেশ দেওয়া থেকে পরামর্শ দেওয়ার দিকে সরে আসুন। পারিবারিক সিদ্ধান্তে তাকে যুক্ত করুন, মত জানতে চান; সম্মান সবচেয়ে ভালো বাড়ে যখন তা দুই দিক থেকেই আসে।"}'::jsonb, 6575, '🫂', 'aap_healthychildren', 'in_review'::lp_review_status, 10031),
  ('ms_y18_own_decisions', 'development', 'cognitive', '{"en":"Makes most everyday decisions and owns the results","bn":"দৈনন্দিন বেশিরভাগ সিদ্ধান্ত নিজে নেয় ও দায় নেয়"}'::jsonb, '{"en":"Most young people by this age make their own everyday decisions, plan ahead and take responsibility when things go wrong — even if they still ask for help with big choices.","bn":"এই বয়সের মধ্যে বেশিরভাগ তরুণ-তরুণী দৈনন্দিন সিদ্ধান্ত নিজে নেয়, আগে থেকে পরিকল্পনা করে, আর কিছু ভুল হলে দায় নেয় — যদিও বড় সিদ্ধান্তে এখনো সাহায্য চাইতে পারে।"}'::jsonb, '{"en":"Let them make choices and learn from small mistakes. When they ask for help, list the options and consequences together rather than deciding for them.","bn":"সিদ্ধান্ত নিতে দিন, ছোট ভুল থেকে শিখতে দিন। সাহায্য চাইলে তার হয়ে সিদ্ধান্ত না নিয়ে একসাথে বিকল্প ও পরিণতিগুলোর তালিকা করুন।"}'::jsonb, 6575, '🧭', 'aap_healthychildren', 'in_review'::lp_review_status, 10032),
  ('ms_y18_manages_health', 'development', 'self_care', '{"en":"Looks after their own health","bn":"নিজের স্বাস্থ্যের যত্ন নিজে নেয়"}'::jsonb, '{"en":"Most young people by this age can go to a doctor on their own, take medicines as prescribed and know basic facts about their own health, such as their blood group and any allergies.","bn":"এই বয়সের মধ্যে বেশিরভাগ তরুণ-তরুণী নিজে ডাক্তারের কাছে যেতে, নিয়মমতো ওষুধ খেতে এবং নিজের স্বাস্থ্যের মূল তথ্য — যেমন রক্তের গ্রুপ, কোনো অ্যালার্জি — জানতে পারে।"}'::jsonb, '{"en":"Hand over their vaccination card and health papers. Make sure they know their blood group, any allergies, the family''s medical history and where the nearest hospital is.","bn":"টিকা কার্ড ও স্বাস্থ্যের কাগজপত্র তার হাতে দিন। রক্তের গ্রুপ, কোনো অ্যালার্জি, পরিবারের অসুখের ইতিহাস আর নিকটস্থ হাসপাতাল কোথায় — এগুলো যেন সে জানে।"}'::jsonb, 6575, '🩺', 'aap_healthychildren', 'in_review'::lp_review_status, 10033),
  ('ms_y18_next_step', 'development', 'learning', '{"en":"Has a plan for the next step after school","bn":"স্কুল-কলেজের পরের ধাপের পরিকল্পনা আছে"}'::jsonb, '{"en":"Most young people by this age, around the HSC, have a plan for what comes next — university, technical training, a job or the family business — even if it changes later.","bn":"এই বয়সের মধ্যে, এইচএসসির আশেপাশে, বেশিরভাগ তরুণ-তরুণীর পরের ধাপের একটা পরিকল্পনা থাকে — বিশ্ববিদ্যালয়, কারিগরি প্রশিক্ষণ, চাকরি বা পারিবারিক ব্যবসা — যদিও পরে তা বদলাতে পারে।"}'::jsonb, '{"en":"Help with forms, deadlines and visits, but let them lead. If a plan does not work out, remind them that many different paths lead to a good life.","bn":"ফর্ম, সময়সীমা ও খোঁজখবরে সাহায্য করুন, তবে নেতৃত্ব তাকে দিন। পরিকল্পনামতো না হলে মনে করিয়ে দিন, ভালো জীবনের পথ একটা নয়, অনেক।"}'::jsonb, 6575, '🚀', 'aap_healthychildren', 'in_review'::lp_review_status, 10034),
  ('ms_y18_formal_communication', 'development', 'language', '{"en":"Speaks and writes formally when needed","bn":"দরকার হলে আনুষ্ঠানিকভাবে বলতে ও লিখতে পারে"}'::jsonb, '{"en":"Most young people by this age can fill in forms, write an application or an email, and speak confidently at an interview or in an office.","bn":"এই বয়সের মধ্যে বেশিরভাগ তরুণ-তরুণী ফর্ম পূরণ করতে, আবেদনপত্র বা ইমেইল লিখতে, আর ইন্টারভিউতে বা কোনো অফিসে আত্মবিশ্বাসের সাথে কথা বলতে পারে।"}'::jsonb, '{"en":"Let them handle real tasks — a bank form, a college application, a phone call to an office. Practise an interview together.","bn":"বাস্তব কাজ তাকে করতে দিন — ব্যাংকের ফর্ম, কলেজের আবেদন, কোনো অফিসে ফোন। একসাথে ইন্টারভিউর অনুশীলন করুন।"}'::jsonb, 6575, '✉️', 'aap_healthychildren', 'in_review'::lp_review_status, 10035),
  ('ms_first_dental_visit', 'health', 'health', '{"en":"First dental check-up","bn":"প্রথম দাঁতের চেকআপ"}'::jsonb, '{"en":"A first dental visit is advised when the first tooth comes through, or by the first birthday. The dentist checks the teeth and gums and shows you how to clean them.","bn":"প্রথম দাঁত ওঠার সময় বা প্রথম জন্মদিনের মধ্যে প্রথমবার দাঁতের ডাক্তারের কাছে যাওয়ার পরামর্শ দেওয়া হয়। ডাক্তার দাঁত ও মাড়ি দেখবেন এবং কীভাবে পরিষ্কার করতে হয় দেখিয়ে দেবেন।"}'::jsonb, '{"en":"Clean the teeth twice a day with a smear of fluoride toothpaste the size of a grain of rice. Do not put the baby to sleep with a bottle, and avoid sweets and sweet drinks.","bn":"দিনে দুইবার চালের দানার সমান সামান্য ফ্লোরাইড টুথপেস্ট দিয়ে দাঁত পরিষ্কার করুন। ফিডার মুখে দিয়ে ঘুম পাড়াবেন না, আর মিষ্টি ও মিষ্টি পানীয় এড়িয়ে চলুন।"}'::jsonb, 365, '🦷', 'aap_healthychildren', 'in_review'::lp_review_status, 10036),
  ('ms_dental_check_regular', 'health', 'health', '{"en":"Dental check every 6 months","bn":"প্রতি ৬ মাসে দাঁতের চেকআপ"}'::jsonb, '{"en":"After the first visit, a dental check about every 6 months — or as often as your dentist advises — finds tooth decay early, when it is easier to treat.","bn":"প্রথমবারের পর মোটামুটি প্রতি ৬ মাসে — বা দাঁতের ডাক্তার যতদিন পরপর বলেন — চেকআপ করালে দাঁতের ক্ষয় শুরুতেই ধরা পড়ে, তখন চিকিৎসা সহজ।"}'::jsonb, '{"en":"Note the date of the next check. Brown or black spots, toothache, swollen gums or bad breath are reasons to go sooner.","bn":"পরের চেকআপের তারিখ লিখে রাখুন। দাঁতে বাদামি বা কালো দাগ, দাঁতব্যথা, মাড়ি ফোলা বা মুখে দুর্গন্ধ হলে আগেই যান।"}'::jsonb, 730, '🪥', 'who_oral_health', 'in_review'::lp_review_status, 10037),
  ('ms_eye_test_before_school', 'health', 'health', '{"en":"Eye test before starting school","bn":"স্কুল শুরুর আগে চোখ পরীক্ষা"}'::jsonb, '{"en":"An eye check at about 4–5 years, before school starts, can find problems such as a lazy eye, a squint or short sight. These are easier to treat when found early.","bn":"স্কুল শুরুর আগে, প্রায় ৪–৫ বছর বয়সে চোখ পরীক্ষা করালে অলস চোখ, ট্যারা চোখ বা দূরের জিনিস ঝাপসা দেখার মতো সমস্যা ধরা পড়ে। আগে ধরা পড়লে চিকিৎসা সহজ।"}'::jsonb, '{"en":"Go sooner if your child screws up their eyes, holds books very close, tilts their head to see, has an eye that turns in or out, or complains of headaches. If glasses are prescribed, help them wear them every day.","bn":"শিশু চোখ কুঁচকে তাকালে, বই খুব কাছে ধরলে, মাথা কাত করে দেখলে, একটা চোখ ভেতরে বা বাইরে সরে গেলে বা মাথাব্যথার কথা বললে আগেই দেখান। চশমা দিলে প্রতিদিন পরতে সাহায্য করুন।"}'::jsonb, 1645, '👓', 'aap_healthychildren', 'in_review'::lp_review_status, 10038),
  ('ms_hearing_check', 'health', 'health', '{"en":"Hearing check if there are concerns","bn":"সন্দেহ হলে কানে শোনার পরীক্ষা"}'::jsonb, '{"en":"At any age, a hearing test is advised if a child does not react to sounds, is slow to talk, often says ''what?'', turns the TV up loud or has had many ear infections. Hearing problems affect speech and learning, and help works best when it starts early.","bn":"যেকোনো বয়সে শিশু শব্দে সাড়া না দিলে, কথা বলতে দেরি করলে, বারবার ''কী?'' জিজ্ঞেস করলে, টিভির আওয়াজ খুব বাড়িয়ে দিলে বা বারবার কানে সংক্রমণ হলে কানে শোনার পরীক্ষা করানো উচিত। শোনার সমস্যা কথা বলা ও শেখায় প্রভাব ফেলে, আর সাহায্য যত আগে শুরু হয় তত ভালো কাজ করে।"}'::jsonb, '{"en":"Tell your doctor about your concern and ask to be referred to an ENT (ear, nose and throat) specialist or a hearing test centre. Never put oil, sticks or anything else into the ear.","bn":"আপনার সন্দেহের কথা ডাক্তারকে বলুন এবং নাক-কান-গলা বিশেষজ্ঞ বা শ্রবণ পরীক্ষাকেন্দ্রে পাঠাতে বলুন। কানে কখনো তেল, কাঠি বা অন্য কিছু ঢোকাবেন না।"}'::jsonb, 548, '👂', 'aap_healthychildren', 'in_review'::lp_review_status, 10039),
  ('ms_growth_check_yearly', 'health', 'health', '{"en":"Yearly height, weight and BMI check","bn":"প্রতি বছর উচ্চতা, ওজন ও বিএমআই দেখা"}'::jsonb, '{"en":"From about 2 years, measuring height and weight once a year and plotting them on a growth chart shows whether a child is growing steadily, growing too slowly, or gaining weight too fast.","bn":"প্রায় ২ বছর বয়স থেকে বছরে একবার উচ্চতা ও ওজন মেপে গ্রোথ চার্টে বসালে বোঝা যায় শিশু ঠিকমতো বাড়ছে, নাকি খুব ধীরে বাড়ছে, বা ওজন খুব দ্রুত বাড়ছে।"}'::jsonb, '{"en":"Ask the doctor or health worker to plot the numbers and explain the result. A child who crosses the lines on the chart, up or down, or is very thin or heavy for their height, should be checked further.","bn":"ডাক্তার বা স্বাস্থ্যকর্মীকে চার্টে বসিয়ে ফলাফল বুঝিয়ে দিতে বলুন। চার্টের রেখা পেরিয়ে নিচে বা ওপরে চলে গেলে, বা উচ্চতার তুলনায় খুব রোগা বা ভারী হলে আরও পরীক্ষা করানো দরকার।"}'::jsonb, 1096, '📈', 'who_growth_standards', 'in_review'::lp_review_status, 10040),
  ('ms_vitamin_a_campaign', 'health', 'health', '{"en":"Vitamin A capsule at the national campaign","bn":"জাতীয় ক্যাম্পেইনে ভিটামিন এ ক্যাপসুল"}'::jsonb, '{"en":"Bangladesh''s national programme gives vitamin A capsules to young children, from 6 months to under 5 years, at regular campaigns. Vitamin A helps protect against serious illness and night blindness.","bn":"বাংলাদেশের জাতীয় কর্মসূচিতে ৬ মাস থেকে ৫ বছরের কম বয়সী শিশুদের নিয়মিত ক্যাম্পেইনে ভিটামিন এ ক্যাপসুল খাওয়ানো হয়। ভিটামিন এ মারাত্মক অসুখ ও রাতকানা রোগ থেকে রক্ষা করতে সাহায্য করে।"}'::jsonb, '{"en":"Listen for campaign announcements from the community clinic, EPI centre or local mosque, and do not miss the day. Health workers give it at the campaign — do not give extra vitamin A at home without a doctor''s advice.","bn":"কমিউনিটি ক্লিনিক, ইপিআই কেন্দ্র বা মসজিদের মাইকে ক্যাম্পেইনের ঘোষণা খেয়াল রাখুন, দিনটা যেন বাদ না পড়ে। ক্যাম্পেইনে স্বাস্থ্যকর্মীরাই খাওয়ান — ডাক্তারের পরামর্শ ছাড়া বাসায় বাড়তি ভিটামিন এ দেবেন না।"}'::jsonb, 183, '💊', NULL, 'in_review'::lp_review_status, 10041),
  ('ms_deworming', 'health', 'health', '{"en":"Deworming as per the national programme","bn":"জাতীয় কর্মসূচি অনুযায়ী কৃমিনাশক"}'::jsonb, '{"en":"Children in Bangladesh are offered deworming tablets through national campaigns, often at school or alongside other child health campaigns. Worms can cause anaemia, poor growth and tiredness.","bn":"বাংলাদেশে জাতীয় ক্যাম্পেইনের মাধ্যমে শিশুদের কৃমিনাশক ট্যাবলেট দেওয়া হয়, প্রায়ই স্কুলে বা অন্যান্য শিশুস্বাস্থ্য ক্যাম্পেইনের সাথে। কৃমি রক্তস্বল্পতা, বৃদ্ধি কমে যাওয়া ও ক্লান্তির কারণ হতে পারে।"}'::jsonb, '{"en":"Follow the campaign or your health worker''s advice on when to give it. Handwashing with soap, wearing shoes or sandals outside, safe water and using a proper toilet all help prevent worms.","bn":"কখন খাওয়াতে হবে তা ক্যাম্পেইন বা স্বাস্থ্যকর্মীর পরামর্শমতো করুন। সাবান দিয়ে হাত ধোয়া, বাইরে জুতা-স্যান্ডেল পরা, নিরাপদ পানি আর স্বাস্থ্যসম্মত টয়লেট ব্যবহার — সবই কৃমি প্রতিরোধে সাহায্য করে।"}'::jsonb, 730, '🪱', NULL, 'in_review'::lp_review_status, 10042),
  ('ms_puberty_starts', 'health', 'health', '{"en":"Puberty begins within the normal age range","bn":"স্বাভাবিক বয়সসীমায় বয়ঃসন্ধি শুরু"}'::jsonb, '{"en":"Puberty usually starts between about 8 and 13 years in girls, often with breast development first, and between about 9 and 14 years in boys, often with growth of the testicles first. Each child has their own timing.","bn":"মেয়েদের বয়ঃসন্ধি সাধারণত প্রায় ৮ থেকে ১৩ বছরের মধ্যে শুরু হয়, প্রায়ই প্রথমে স্তনের বৃদ্ধি দিয়ে; আর ছেলেদের প্রায় ৯ থেকে ১৪ বছরের মধ্যে, প্রায়ই প্রথমে অণ্ডকোষের বৃদ্ধি দিয়ে। প্রতিটি শিশুর সময় আলাদা।"}'::jsonb, '{"en":"Explain the changes before they start, calmly and simply. See a doctor if signs appear before 8 in a girl or before 9 in a boy, or if there are no signs by 13 in a girl or 14 in a boy.","bn":"পরিবর্তন শুরুর আগেই শান্তভাবে, সহজ কথায় বুঝিয়ে বলুন। মেয়ের ৮ বছরের আগে বা ছেলের ৯ বছরের আগে লক্ষণ দেখা দিলে, অথবা মেয়ের ১৩ বা ছেলের ১৪ বছরেও কোনো লক্ষণ না দেখা দিলে ডাক্তার দেখান।"}'::jsonb, 3652, '🌱', 'aap_healthychildren', 'in_review'::lp_review_status, 10043),
  ('ms_first_period', 'health', 'health', '{"en":"First period (girls)","bn":"প্রথম মাসিক (মেয়েদের)"}'::jsonb, '{"en":"Most girls have their first period between about 10 and 15 years, usually around two years after their breasts start to develop. Periods are often irregular for the first year or two.","bn":"বেশিরভাগ মেয়ের প্রথম মাসিক হয় প্রায় ১০ থেকে ১৫ বছরের মধ্যে, সাধারণত স্তন বাড়তে শুরু করার প্রায় দুই বছর পরে। প্রথম এক-দুই বছর মাসিক প্রায়ই অনিয়মিত থাকে।"}'::jsonb, '{"en":"Prepare her before it happens: what a period is, how to use pads, how to stay clean, and that it is normal and nothing to be ashamed of. Keep a pad in her school bag. See a doctor if there is no period by 15, bleeding is very heavy, or pain keeps her from school.","bn":"মাসিক হওয়ার আগেই তাকে প্রস্তুত করুন: মাসিক কী, কীভাবে প্যাড ব্যবহার করতে হয়, কীভাবে পরিষ্কার থাকতে হয়, আর এটা স্বাভাবিক — লজ্জার কিছু নয়। স্কুলব্যাগে একটা প্যাড রেখে দিন। ১৫ বছরেও মাসিক না হলে, রক্তপাত খুব বেশি হলে, বা ব্যথায় স্কুলে যেতে না পারলে ডাক্তার দেখান।"}'::jsonb, 4383, '🌸', 'aap_healthychildren', 'in_review'::lp_review_status, 10044),
  ('ms_hpv_vaccine', 'health', 'health', '{"en":"HPV vaccine (girls)","bn":"এইচপিভি টিকা (মেয়েদের)"}'::jsonb, '{"en":"Bangladesh''s national programme offers the HPV vaccine to girls of about 10–14 years, often at school. It protects against the virus that causes most cervical cancer.","bn":"বাংলাদেশের জাতীয় কর্মসূচিতে প্রায় ১০–১৪ বছরের মেয়েদের এইচপিভি টিকা দেওয়া হয়, প্রায়ই স্কুলে। এটি সেই ভাইরাস থেকে রক্ষা করে, যা জরায়ুমুখ ক্যান্সারের বেশিরভাগের কারণ।"}'::jsonb, '{"en":"Watch for the school or EPI campaign dates and keep the card safe. Girls who are not in school can also get it during the campaign — ask your health worker where.","bn":"স্কুল বা ইপিআই ক্যাম্পেইনের তারিখ খেয়াল রাখুন এবং কার্ড যত্ন করে রাখুন। যে মেয়েরা স্কুলে যায় না, তারাও ক্যাম্পেইনের সময় টিকা নিতে পারে — কোথায় দেওয়া হচ্ছে স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন।"}'::jsonb, 3652, '💉', 'dghs_epi', 'in_review'::lp_review_status, 10045),
  ('ms_td_adolescent_girl', 'health', 'health', '{"en":"Td vaccine for adolescent girls","bn":"কিশোরীদের টিডি টিকা"}'::jsonb, '{"en":"Bangladesh''s EPI offers Td (tetanus-diphtheria) doses to girls and women from 15 years. The full course protects her, and later her newborn babies, from tetanus.","bn":"বাংলাদেশের ইপিআই ১৫ বছর বয়স থেকে মেয়ে ও নারীদের টিডি (ধনুষ্টংকার-ডিফথেরিয়া) টিকা দেয়। পুরো কোর্স তাকে এবং ভবিষ্যতে তার নবজাতককে ধনুষ্টংকার থেকে রক্ষা করে।"}'::jsonb, '{"en":"Take her to the EPI centre with her card and keep track of the 5 doses and the gaps between them. Doses given earlier still count.","bn":"কার্ডসহ ইপিআই কেন্দ্রে নিয়ে যান, আর ৫টি ডোজ ও তাদের মাঝের বিরতির হিসাব রাখুন। আগে নেওয়া ডোজগুলোও গোনা হয়।"}'::jsonb, 5479, '💉', 'dghs_epi', 'in_review'::lp_review_status, 10046),
  ('ms_anaemia_check_teen_girl', 'health', 'health', '{"en":"Blood test for anaemia if tired or pale","bn":"ক্লান্ত বা ফ্যাকাশে হলে রক্তস্বল্পতার পরীক্ষা"}'::jsonb, '{"en":"Anaemia is common in adolescent girls, especially after periods start. If she is often tired, pale, breathless, dizzy or finds it hard to concentrate, a simple blood test (haemoglobin) can check for it.","bn":"কিশোরীদের মধ্যে, বিশেষ করে মাসিক শুরুর পর, রক্তস্বল্পতা বেশ সাধারণ। প্রায়ই ক্লান্ত লাগা, ফ্যাকাশে হওয়া, শ্বাসকষ্ট, মাথা ঘোরা বা মনোযোগে কষ্ট হলে রক্তের একটা সহজ পরীক্ষা (হিমোগ্লোবিন) দিয়ে তা দেখা যায়।"}'::jsonb, '{"en":"Ask your doctor about the test and follow the treatment they give. Offer iron-rich foods — fish, meat, eggs, liver, dal, dark green leafy vegetables — with fruit rich in vitamin C, such as guava or lemon. Very heavy periods also need a doctor''s check.","bn":"পরীক্ষার ব্যাপারে ডাক্তারকে জিজ্ঞেস করুন এবং তাঁর দেওয়া চিকিৎসা মেনে চলুন। আয়রনসমৃদ্ধ খাবার দিন — মাছ, মাংস, ডিম, কলিজা, ডাল, গাঢ় সবুজ শাক — সাথে ভিটামিন সি-যুক্ত ফল, যেমন পেয়ারা বা লেবু। মাসিকে খুব বেশি রক্তপাত হলেও ডাক্তার দেখানো দরকার।"}'::jsonb, 4748, '🩸', 'who_adolescent_health', 'in_review'::lp_review_status, 10047),
  ('ms_thalassaemia_carrier_test', 'health', 'health', '{"en":"Thalassaemia carrier test before marriage","bn":"বিয়ের আগে থ্যালাসেমিয়া বাহক পরীক্ষা"}'::jsonb, '{"en":"Thalassaemia carriers are common in Bangladesh and usually feel completely well. If both partners are carriers, each pregnancy has a 1 in 4 chance of a baby with thalassaemia major, a serious lifelong blood disease. A blood test (haemoglobin electrophoresis) shows whether someone is a carrier.","bn":"বাংলাদেশে থ্যালাসেমিয়ার বাহক অনেক, আর বাহকেরা সাধারণত পুরোপুরি সুস্থ থাকেন। স্বামী-স্ত্রী দুজনেই বাহক হলে প্রতিটি গর্ভে সন্তানের থ্যালাসেমিয়া মেজর — আজীবনের একটি গুরুতর রক্তরোগ — নিয়ে জন্মানোর সম্ভাবনা ৪ ভাগের ১ ভাগ। রক্তের একটি পরীক্ষা (হিমোগ্লোবিন ইলেকট্রোফোরেসিস) দিয়ে জানা যায় কেউ বাহক কিনা।"}'::jsonb, '{"en":"Encourage your young adult to have the test before marriage and to share the result with the other family. Being a carrier is not an illness and nothing to hide; knowing early gives a couple choices and support.","bn":"বিয়ের আগে সন্তানকে পরীক্ষাটি করাতে উৎসাহ দিন, আর ফলাফল অন্য পরিবারকে জানাতে বলুন। বাহক হওয়া কোনো অসুখ নয়, লুকানোরও কিছু নয়; আগে জানলে দম্পতি সিদ্ধান্ত নেওয়ার সুযোগ ও সহায়তা পান।"}'::jsonb, 6575, '🧬', NULL, 'in_review'::lp_review_status, 10048),
  ('ms_first_day_school', 'family', 'learning', '{"en":"First day at school","bn":"স্কুলের প্রথম দিন"}'::jsonb, '{"en":"Starting school — pre-primary or class one — is a big step for the whole family. Some children run in happily; others cry for days. Both are normal.","bn":"স্কুল শুরু — প্রাক-প্রাথমিক বা প্রথম শ্রেণি — পুরো পরিবারের জন্য বড় একটা ধাপ। কোনো শিশু হাসিমুখে ঢুকে যায়, কেউ কয়েক দিন কাঁদে। দুটোই স্বাভাবিক।"}'::jsonb, '{"en":"Visit the school together beforehand and talk about what will happen. Say a short, warm goodbye and tell them who will pick them up. Take a photo — the father or a grandparent can come along for the drop-off too.","bn":"আগে থেকে একসাথে স্কুলটা ঘুরে আসুন এবং কী হবে তা নিয়ে গল্প করুন। ছোট্ট, উষ্ণ বিদায় দিন আর বলে দিন কে নিতে আসবে। একটা ছবি তুলে রাখুন — বাবা বা দাদা-দাদি, নানা-নানিও পৌঁছে দিতে সাথে যেতে পারেন।"}'::jsonb, 1826, '🎒', NULL, 'in_review'::lp_review_status, 10049),
  ('ms_reads_book_alone', 'family', 'learning', '{"en":"Read a whole book alone for the first time","bn":"প্রথমবার একা পুরো একটা বই পড়ল"}'::jsonb, '{"en":"The day your child reads a whole short book by themselves — in Bangla, English or any language — is worth celebrating. It often happens around 7, but every child''s timing is different.","bn":"যেদিন সন্তান একা একটা ছোট বই পুরোটা পড়ে — বাংলা, ইংরেজি বা যেকোনো ভাষায় — সেদিনটা উদযাপনের মতো। প্রায়ই এটা ৭ বছরের আশেপাশে হয়, তবে প্রতিটি শিশুর সময় আলাদা।"}'::jsonb, '{"en":"Let them choose books they enjoy, even comics. Ask them to read to a younger sibling or a grandparent. A trip to a library or a book fair makes a lovely reward.","bn":"পছন্দের বই বেছে নিতে দিন, কমিকস হলেও। ছোট ভাইবোন বা দাদা-দাদি, নানা-নানিকে পড়ে শোনাতে বলুন। লাইব্রেরি বা বইমেলায় বেড়াতে যাওয়া চমৎকার পুরস্কার হতে পারে।"}'::jsonb, 2557, '📚', NULL, 'in_review'::lp_review_status, 10050),
  ('ms_memorised_fatiha', 'family', 'islamic', '{"en":"Memorised Surah Al-Fatiha","bn":"সূরা আল-ফাতিহা মুখস্থ করল"}'::jsonb, '{"en":"Al-Fatiha (Surah 1) is recited in every unit (rak''ah) of salah, so it is usually the first surah children learn by heart, often around 5 years.","bn":"সালাতের প্রতিটি রাকাতে আল-ফাতিহা (সূরা ১) পড়া হয়, তাই সাধারণত শিশুরা এটিই প্রথম মুখস্থ করে, প্রায়ই ৫ বছরের আশেপাশে।"}'::jsonb, '{"en":"Recite it together every day, one ayah at a time, and explain the meaning simply in Bangla. Correct gently and praise often.","bn":"প্রতিদিন একসাথে এক আয়াত করে পড়ুন, আর সহজ বাংলায় অর্থ বুঝিয়ে দিন। নরমভাবে শুধরে দিন, বেশি বেশি প্রশংসা করুন।"}'::jsonb, 1826, '🤲', 'quran', 'in_review'::lp_review_status, 10051),
  ('ms_finished_qaida', 'family', 'islamic', '{"en":"Finished the Qaida","bn":"কায়দা শেষ করল"}'::jsonb, '{"en":"Finishing the Qaida (such as the Noorani Qaida) means your child can recognise the Arabic letters and join them to read words — the step before reading the Quran itself. Many children finish it around 6–7 years.","bn":"কায়দা (যেমন নূরানী কায়দা) শেষ করা মানে সন্তান আরবি হরফ চেনে এবং হরফ মিলিয়ে শব্দ পড়তে পারে — কুরআন পড়া শুরুর আগের ধাপ। অনেক শিশু ৬–৭ বছরের আশেপাশে এটি শেষ করে।"}'::jsonb, '{"en":"A few minutes a day works better than long sessions. Choose a kind teacher, sit with your child sometimes, and celebrate when they finish — many families share sweets and begin the first Quran lesson with a dua.","bn":"লম্বা সময়ের চেয়ে প্রতিদিন কয়েক মিনিট বেশি কাজে দেয়। দয়ালু শিক্ষক বেছে নিন, মাঝে মাঝে পাশে বসুন, আর শেষ হলে উদযাপন করুন — অনেক পরিবার মিষ্টি বিতরণ করে এবং দোয়া দিয়ে কুরআনের প্রথম পাঠ শুরু করে।"}'::jsonb, 2374, '📗', NULL, 'in_review'::lp_review_status, 10052),
  ('ms_first_salah_family', 'family', 'islamic', '{"en":"First salah prayed with the family","bn":"পরিবারের সাথে প্রথম সালাত"}'::jsonb, '{"en":"The Prophet ﷺ instructed parents to tell their children to pray when they reach seven (Sunan Abi Dawud 495). Praying beside a parent for the first time is a gentle, joyful start.","bn":"রাসূলুল্লাহ ﷺ সন্তানের বয়স সাত হলে তাকে সালাতের কথা বলতে মা-বাবাকে নির্দেশ দিয়েছেন (সুনানে আবু দাউদ ৪৯৫)। মা বা বাবার পাশে দাঁড়িয়ে প্রথমবার সালাত আদায় একটি কোমল, আনন্দময় সূচনা।"}'::jsonb, '{"en":"Let them stand beside you, even if they only copy the movements. Teach wudu step by step, praise every attempt, and never shame or force. A small prayer mat of their own can make it special.","bn":"আপনার পাশে দাঁড়াতে দিন, শুধু নড়াচড়া নকল করলেও। ধাপে ধাপে অজু শেখান, প্রতিটি চেষ্টার প্রশংসা করুন, কখনো লজ্জা দেবেন না বা জোর করবেন না। তার নিজের ছোট্ট একটা জায়নামাজ ব্যাপারটাকে বিশেষ করে তুলতে পারে।"}'::jsonb, 2557, '🕌', 'hadith_abudawud_495', 'in_review'::lp_review_status, 10053),
  ('ms_first_money_saved', 'family', 'self_care', '{"en":"Saved their own money for the first time","bn":"প্রথমবার নিজের টাকা জমাল"}'::jsonb, '{"en":"Around 10, many children can save part of their pocket money or Eid salami for something they want. Learning to wait, to plan and to give some to others is a skill for life.","bn":"১০ বছরের আশেপাশে অনেক শিশু হাতখরচ বা ঈদের সালামির একটা অংশ জমিয়ে পছন্দের কিছুর জন্য রাখতে পারে। অপেক্ষা করা, পরিকল্পনা করা আর কিছুটা অন্যকে দেওয়া — সারাজীবনের দক্ষতা।"}'::jsonb, '{"en":"Give a clay piggy bank (matir bank) or a simple box with three parts: save, spend, give. Write the goal down and celebrate when they reach it.","bn":"একটা মাটির ব্যাংক বা তিন ভাগের একটা কৌটা দিন: জমানো, খরচ, দান। লক্ষ্যটা লিখে রাখুন, আর পৌঁছালে উদযাপন করুন।"}'::jsonb, 3652, '🐷', NULL, 'in_review'::lp_review_status, 10054),
  ('ms_first_full_fast', 'family', 'islamic', '{"en":"First full day of fasting in Ramadan","bn":"রমজানে প্রথম পুরো দিনের রোজা"}'::jsonb, '{"en":"Fasting becomes obligatory at puberty (bulugh). Many children practise with part-days first and keep their first full fast close to puberty, health permitting. The Companions used to help their young children practise fasting (Sahih al-Bukhari).","bn":"বালেগ (বয়ঃপ্রাপ্ত) হলে রোজা ফরজ হয়। অনেক শিশু আগে দিনের কিছু অংশ রোজা রেখে অভ্যাস করে, আর স্বাস্থ্য অনুমতি দিলে বয়ঃসন্ধির কাছাকাছি প্রথম পুরো রোজা রাখে। সাহাবিরা তাঁদের ছোট সন্তানদের রোজার অভ্যাস করাতেন (সহিহ বুখারি)।"}'::jsonb, '{"en":"Start with a few hours or half a day. Make sure they eat a good sehri and drink enough between iftar and sehri. If they feel unwell, dizzy or very weak, let them break the fast — there is no shame in it. If your child has a long-term illness, ask the doctor first.","bn":"কয়েক ঘণ্টা বা অর্ধেক দিন দিয়ে শুরু করুন। সেহরিতে ভালো করে খাওয়া আর ইফতার থেকে সেহরি পর্যন্ত যথেষ্ট পানি পান নিশ্চিত করুন। অসুস্থ লাগলে, মাথা ঘুরলে বা খুব দুর্বল লাগলে রোজা ভেঙে ফেলতে দিন — এতে লজ্জার কিছু নেই। সন্তানের দীর্ঘমেয়াদি কোনো অসুখ থাকলে আগে ডাক্তারের পরামর্শ নিন।"}'::jsonb, 3652, '🌙', 'sahih_bukhari', 'in_review'::lp_review_status, 10055),
  ('ms_planned_family_trip', 'family', 'cognitive', '{"en":"Planned a family outing or trip","bn":"পরিবারের একটা বেড়ানো নিজে পরিকল্পনা করল"}'::jsonb, '{"en":"Around 12, many children can plan a day out or a short family trip — choosing the place, checking the cost and making a list. It builds confidence and responsibility.","bn":"১২ বছরের আশেপাশে অনেক শিশু একদিনের বেড়ানো বা ছোট পারিবারিক ভ্রমণ পরিকল্পনা করতে পারে — জায়গা বাছাই, খরচ দেখা, তালিকা বানানো। এতে আত্মবিশ্বাস ও দায়িত্ববোধ বাড়ে।"}'::jsonb, '{"en":"Give a budget and a few choices — a park, a relative''s village, a museum. Let them plan the timing, food and what to pack, and follow their plan even if it is not perfect.","bn":"একটা বাজেট আর কয়েকটা বিকল্প দিন — পার্ক, গ্রামে কোনো আত্মীয়ের বাড়ি, জাদুঘর। সময়, খাবার আর কী সাথে নিতে হবে তা তাকেই ঠিক করতে দিন, আর নিখুঁত না হলেও তার পরিকল্পনামতোই যান।"}'::jsonb, 4383, '🗺️', NULL, 'in_review'::lp_review_status, 10056)
INSERT INTO lp_counter_templates (key, title, description, why, safety_note, emoji, unit, input, step, target, target_kind, period, subject, min_day, max_day, sex, xp, category_key, source_key, review_status, sort_order) VALUES
  ('ct_water_child', '{"en":"Glasses of water","bn":"পানি (গ্লাস)"}'::jsonb, '{}'::jsonb, '{"en":"Water is the best drink for children. Most children of this age need around 5–6 glasses a day, and more in hot weather or after sport.","bn":"শিশুর জন্য পানিই সবচেয়ে ভালো পানীয়। এই বয়সের বেশিরভাগ শিশুর দিনে প্রায় ৫–৬ গ্লাস দরকার; গরমে বা খেলাধুলার পরে আরও বেশি।"}'::jsonb, '{"en":"Give safe water — boiled, filtered or from an arsenic-safe tube well. If a doctor has asked you to limit fluids, follow that instead.","bn":"নিরাপদ পানি দিন — ফোটানো, ফিল্টার করা বা আর্সেনিকমুক্ত নলকূপের। ডাক্তার পানি কম দিতে বললে সেটিই মেনে চলুন।"}'::jsonb, '💧', 'glasses', 'tap', 1, 5, 'at_least', 'day', 'child', 1461, 4748, 'any', 2, 'nutrition', NULL, 'in_review'::lp_review_status, 10101),
  ('ct_fruit_veg', '{"en":"Fruit and vegetable portions","bn":"ফল ও শাকসবজি (পরিবেশন)"}'::jsonb, '{}'::jsonb, '{"en":"Aim for at least 5 portions of fruit and vegetables a day. For a child, a portion is roughly what fits in their own cupped hand. Local seasonal foods — shak, pumpkin, guava, banana, papaya — all count.","bn":"দিনে অন্তত ৫ বার ফল ও শাকসবজি খাওয়ানোর চেষ্টা করুন। শিশুর জন্য এক পরিবেশন মোটামুটি তার নিজের এক মুঠোয় যতটা ধরে। দেশি মৌসুমি শাক, মিষ্টিকুমড়া, পেয়ারা, কলা, পেঁপে — সবই গোনা যায়।"}'::jsonb, '{"en":"Wash fruit and vegetables in safe water. For children under 5, cut round foods such as grapes into small pieces so they do not choke.","bn":"ফল ও সবজি নিরাপদ পানিতে ধুয়ে নিন। ৫ বছরের কম শিশুর জন্য আঙুরের মতো গোল খাবার ছোট টুকরো করে দিন, যাতে গলায় না আটকায়।"}'::jsonb, '🥦', 'times', 'tap', 1, 5, 'at_least', 'day', 'child', 730, 7305, 'any', 3, 'nutrition', NULL, 'in_review'::lp_review_status, 10102),
  ('ct_outdoor_time', '{"en":"Time outdoors","bn":"বাইরে কাটানো সময়"}'::jsonb, '{}'::jsonb, '{"en":"Playing or walking outside in daylight helps children move more, sleep better and rest their eyes from close-up work. Aim for at least 60 minutes; it can be the same time as active play.","bn":"দিনের আলোয় বাইরে খেলা বা হাঁটা শিশুকে বেশি নড়াচড়া করতে, ভালো ঘুমাতে আর কাছের কাজ থেকে চোখকে বিশ্রাম দিতে সাহায্য করে। দিনে অন্তত ৬০ মিনিটের চেষ্টা করুন; সক্রিয় খেলার সময়ও এর মধ্যে পড়তে পারে।"}'::jsonb, '{"en":"In summer avoid the hottest midday hours and keep water handy. Make sure an adult knows where the child is, especially near ponds, rivers and roads.","bn":"গরমকালে দুপুরের কড়া রোদ এড়িয়ে চলুন, সাথে পানি রাখুন। শিশু কোথায় আছে কোনো বড় মানুষ যেন জানে — বিশেষ করে পুকুর, নদী ও রাস্তার কাছে।"}'::jsonb, '🌳', 'minutes', 'timer', 1, 60, 'at_least', 'day', 'child', 1826, 6575, 'any', 3, 'physical_activity', NULL, 'in_review'::lp_review_status, 10103),
  ('ct_screen_time_5_12', '{"en":"Recreational screen time","bn":"বিনোদনের স্ক্রিন টাইম"}'::jsonb, '{}'::jsonb, '{"en":"A common guide for school-age children is no more than about 2 hours a day of screens for fun, not counting schoolwork. What matters most is that screens do not replace sleep, play, homework and family time.","bn":"স্কুলবয়সী শিশুর জন্য একটি প্রচলিত নির্দেশনা হলো, পড়ালেখার কাজ বাদে বিনোদনের স্ক্রিন দিনে প্রায় ২ ঘণ্টার বেশি নয়। সবচেয়ে জরুরি হলো, স্ক্রিন যেন ঘুম, খেলা, পড়া আর পরিবারের সময়ের জায়গা না নেয়।"}'::jsonb, '{"en":"Keep screens out of the bedroom at night and switch them off an hour before sleep. Know which apps and games your child uses.","bn":"রাতে শোবার ঘরে স্ক্রিন রাখবেন না, ঘুমের এক ঘণ্টা আগে বন্ধ করুন। সন্তান কোন অ্যাপ ও গেম ব্যবহার করে, তা জানুন।"}'::jsonb, '📱', 'minutes', 'timer', 1, 120, 'at_most', 'day', 'child', 1826, 4748, 'any', 0, 'digital_life', NULL, 'in_review'::lp_review_status, 10104),
  ('ct_screen_time_teen', '{"en":"Recreational screen time","bn":"বিনোদনের স্ক্রিন টাইম"}'::jsonb, '{}'::jsonb, '{"en":"Keeping screens for fun to about 2 hours a day, not counting study, helps protect a teenager''s sleep, exercise and real-life friendships. Agree the limit together — teenagers keep rules they helped to make.","bn":"পড়ালেখা বাদে বিনোদনের স্ক্রিন দিনে প্রায় ২ ঘণ্টার মধ্যে রাখলে কিশোর-কিশোরীর ঘুম, ব্যায়াম ও বাস্তব জীবনের বন্ধুত্ব রক্ষা পায়। সীমাটা একসাথে ঠিক করুন — নিজে বানানো নিয়ম কিশোরেরা বেশি মানে।"}'::jsonb, '{"en":"Talk about online safety: never send private photos, and tell a trusted adult about anything that feels wrong — blackmail, bullying, or a stranger asking to meet.","bn":"অনলাইন নিরাপত্তা নিয়ে কথা বলুন: কখনো ব্যক্তিগত ছবি পাঠাবে না, আর কিছু ভুল মনে হলে — ব্ল্যাকমেইল, বুলিং বা অপরিচিত কেউ দেখা করতে চাইলে — বিশ্বস্ত কোনো বড় মানুষকে জানাবে।"}'::jsonb, '📲', 'minutes', 'timer', 1, 120, 'at_most', 'day', 'child', 4748, 7305, 'any', 0, 'digital_life', NULL, 'in_review'::lp_review_status, 10105),
  ('ct_study_minutes', '{"en":"Self-study","bn":"নিজে পড়া"}'::jsonb, '{}'::jsonb, '{"en":"Steady daily self-study, outside class and coaching, builds real understanding and makes exams less stressful than last-minute cramming.","bn":"ক্লাস ও কোচিংয়ের বাইরে প্রতিদিন নিয়মিত নিজে পড়লে বিষয় সত্যিই বোঝা যায়, আর শেষ মুহূর্তের তাড়াহুড়ার চেয়ে পরীক্ষার চাপ কম লাগে।"}'::jsonb, '{"en":"Regular short breaks, enough sleep and some exercise help learning more than extra hours. If study stress brings poor sleep, headaches or low mood, talk about it and get help.","bn":"মাঝে মাঝে ছোট বিরতি, যথেষ্ট ঘুম আর কিছু ব্যায়াম বাড়তি ঘণ্টার চেয়ে শেখায় বেশি সাহায্য করে। পড়ার চাপে ঘুম না হলে, মাথাব্যথা বা মন খারাপ থাকলে কথা বলুন ও সাহায্য নিন।"}'::jsonb, '📚', 'minutes', 'timer', 1, 120, 'at_least', 'day', 'child', 4748, 7305, 'any', 5, 'academics', NULL, 'in_review'::lp_review_status, 10106),
  ('ct_quran_pages', '{"en":"Quran pages read","bn":"কুরআন তিলাওয়াত (পৃষ্ঠা)"}'::jsonb, '{}'::jsonb, '{"en":"Reading a little every day — even one page — keeps a child close to the Quran. Small and steady is better than a lot now and then.","bn":"প্রতিদিন অল্প অল্প — এমনকি এক পৃষ্ঠা — পড়লেও শিশু কুরআনের কাছাকাছি থাকে। মাঝে মাঝে অনেক পড়ার চেয়ে অল্প অল্প নিয়মিত পড়া ভালো।"}'::jsonb, '{"en":"Qaida and Ampara pages count too. Keep it joyful — never punish or shame a child over Quran reading.","bn":"কায়দা ও আমপারার পৃষ্ঠাও গোনা যায়। আনন্দের মধ্যে রাখুন — কুরআন পড়া নিয়ে কখনো শাস্তি দেবেন না বা লজ্জা দেবেন না।"}'::jsonb, '📖', 'pages', 'tap', 1, 7, 'at_least', 'week', 'child', 2557, NULL, 'any', 3, 'quran', NULL, 'in_review'::lp_review_status, 10107),
  ('ct_salah_on_time', '{"en":"Salah on time","bn":"সময়মতো সালাত"}'::jsonb, '{}'::jsonb, '{"en":"Allah says that salah is prescribed for the believers at fixed times (Quran 4:103). Gently counting prayers helps a child build the habit step by step.","bn":"আল্লাহ বলেছেন, মুমিনদের ওপর সালাত নির্দিষ্ট সময়ে ফরজ করা হয়েছে (সূরা আন-নিসা ৪:১০৩)। আলতোভাবে গুনে রাখলে শিশু ধাপে ধাপে অভ্যাস গড়ে তোলে।"}'::jsonb, '{"en":"This is for encouragement, not pressure. Praise each prayer, pray together when you can, and never shame, threaten or compare.","bn":"এটা উৎসাহ দেওয়ার জন্য, চাপ দেওয়ার জন্য নয়। প্রতিটি সালাতের প্রশংসা করুন, সম্ভব হলে একসাথে পড়ুন, আর কখনো লজ্জা দেবেন না, ভয় দেখাবেন না বা অন্যের সাথে তুলনা করবেন না।"}'::jsonb, '🕌', 'times', 'tap', 1, 5, 'at_least', 'day', 'child', 3652, NULL, 'any', 2, 'salah', 'quran', 'in_review'::lp_review_status, 10108),
  ('ct_kangaroo_care', '{"en":"Kangaroo care (hours)","bn":"ক্যাঙ্গারু মাদার কেয়ার (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"For small or premature babies, WHO recommends kangaroo care — the baby held skin-to-skin on the mother''s or father''s chest — for as many hours a day as possible. It helps the baby stay warm, feed well and grow.","bn":"ছোট বা অপরিণত (প্রিম্যাচিউর) শিশুর জন্য বিশ্ব স্বাস্থ্য সংস্থা ক্যাঙ্গারু কেয়ারের পরামর্শ দেয় — মা বা বাবার বুকে চামড়ায় চামড়া লাগিয়ে শিশুকে রাখা — দিনে যত বেশি ঘণ্টা সম্ভব। এতে শিশু উষ্ণ থাকে, ভালো খায় ও বাড়ে।"}'::jsonb, '{"en":"Use this only if advised, and follow the hours and method your hospital gives. The father, grandmother and others can take turns. If the baby is cold, not feeding, breathing fast or hard to wake, go to the hospital at once.","bn":"পরামর্শ দেওয়া হলেই এটি ব্যবহার করুন, আর হাসপাতাল যে নিয়ম ও যত ঘণ্টা বলেছে তা মেনে চলুন। বাবা, দাদি-নানি ও পরিবারের অন্যরাও পালা করে দিতে পারেন। শিশু ঠান্ডা হয়ে গেলে, না খেলে, দ্রুত শ্বাস নিলে বা জাগাতে কষ্ট হলে সাথে সাথে হাসপাতালে যান।"}'::jsonb, '🦘', 'hours', 'amount', 0.5, 8, 'at_least', 'day', 'child', 0, 60, 'any', 5, 'newborn_care', 'who_preterm_lbw_2022', 'in_review'::lp_review_status, 10109),
  ('ct_pumped_milk', '{"en":"Expressed breast milk (ml)","bn":"চেপে বের করা বুকের দুধ (মিলি)"}'::jsonb, '{}'::jsonb, '{"en":"Noting how much milk you express helps you see your supply and plan feeds for when you are away from your baby, such as after returning to work.","bn":"কতটা দুধ চেপে বের করছেন তা লিখে রাখলে দুধের পরিমাণ বোঝা যায়, আর শিশুর কাছ থেকে দূরে থাকার সময়ের — যেমন কাজে ফেরার পর — খাওয়ানোর পরিকল্পনা সহজ হয়।"}'::jsonb, '{"en":"Amounts vary a lot between mothers and between sessions, and pumping does not show how much your baby gets from the breast. Store milk in a clean, covered container, use it within the time your health worker advises (sooner in hot weather), and feed it by cup or spoon.","bn":"পরিমাণ মায়ে মায়ে ও বারে বারে অনেক আলাদা হয়, আর চেপে বের করা দুধ দেখে বোঝা যায় না শিশু বুক থেকে কতটা পাচ্ছে। দুধ পরিষ্কার, ঢাকনাওয়ালা পাত্রে রাখুন, স্বাস্থ্যকর্মী যতক্ষণের মধ্যে বলেন তার মধ্যেই ব্যবহার করুন (গরমে আরও আগে), আর কাপ বা চামচে খাওয়ান।"}'::jsonb, '🍼', 'ml', 'amount', 10, NULL, 'at_least', 'day', 'child', 0, 365, 'any', 0, 'bf_expressing', NULL, 'in_review'::lp_review_status, 10110),
  ('ct_mother_iron_postnatal', '{"en":"Mother''s iron tablet","bn":"মায়ের আয়রন ট্যাবলেট"}'::jsonb, '{}'::jsonb, '{"en":"After birth, many mothers are advised to keep taking iron, often with folic acid, for some weeks. It helps rebuild blood lost in pregnancy and birth and prevents anaemia.","bn":"প্রসবের পর অনেক মাকে কয়েক সপ্তাহ আয়রন (প্রায়ই ফলিক অ্যাসিডসহ) চালিয়ে যেতে বলা হয়। এটি গর্ভাবস্থা ও প্রসবে হারানো রক্ত পূরণ করতে এবং রক্তস্বল্পতা প্রতিরোধে সাহায্য করে।"}'::jsonb, '{"en":"Take only what your health worker prescribed, for as long as advised. Keep iron tablets out of children''s reach — too many can be very dangerous for a child.","bn":"স্বাস্থ্যকর্মী যা দিয়েছেন শুধু সেটাই, যতদিন বলেছেন ততদিন খাবেন। আয়রন ট্যাবলেট শিশুদের নাগালের বাইরে রাখুন — শিশু বেশি খেয়ে ফেললে খুব বিপজ্জনক হতে পারে।"}'::jsonb, '💊', 'tablets', 'tap', 1, 1, 'at_least', 'day', 'family', 0, 90, 'any', 3, 'mother_recovery', 'who_postnatal_2022', 'in_review'::lp_review_status, 10111),
  ('ct_sleep_3_5', '{"en":"Sleep (hours)","bn":"ঘুম (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"Children of 3–5 years usually need 10–13 hours of sleep in 24 hours, which may include a nap. A regular bedtime helps.","bn":"৩–৫ বছরের শিশুর সাধারণত ২৪ ঘণ্টায় ১০–১৩ ঘণ্টা ঘুম দরকার, দুপুরের ঘুমসহ। প্রতিদিন একই সময়ে শোয়ানো সাহায্য করে।"}'::jsonb, '{"en":"Loud snoring with pauses in breathing, or great difficulty waking, is worth mentioning to a doctor.","bn":"জোরে নাক ডাকা আর মাঝে মাঝে শ্বাস থেমে যাওয়া, বা জাগাতে খুব কষ্ট হলে ডাক্তারকে জানান।"}'::jsonb, '😴', 'hours', 'amount', 0.5, 10, 'at_least', 'day', 'child', 1096, 2192, 'any', 0, 'sleep', 'who_activity_under5', 'in_review'::lp_review_status, 10112),
  ('ct_sleep_6_12', '{"en":"Sleep (hours)","bn":"ঘুম (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"Children of 6–12 years usually need 9–12 hours of sleep a night. Enough sleep helps attention, mood and learning.","bn":"৬–১২ বছরের শিশুর সাধারণত রাতে ৯–১২ ঘণ্টা ঘুম দরকার। পর্যাপ্ত ঘুম মনোযোগ, মেজাজ ও শেখায় সাহায্য করে।"}'::jsonb, '{"en":"Loud snoring, very restless sleep or being sleepy all day despite enough hours is worth mentioning to a doctor.","bn":"জোরে নাক ডাকা, খুব অস্থির ঘুম, বা যথেষ্ট ঘুমানোর পরও সারাদিন ঘুম ঘুম ভাব থাকলে ডাক্তারকে জানান।"}'::jsonb, '🌙', 'hours', 'amount', 0.5, 9, 'at_least', 'day', 'child', 2192, 4748, 'any', 0, 'sleep', 'aap_healthychildren', 'in_review'::lp_review_status, 10113),
  ('ct_family_meals', '{"en":"Family meals together","bn":"পরিবারের সবাই একসাথে খাওয়া"}'::jsonb, '{"en":"Count any meal or iftar where most of the family sits down together.","bn":"যে বেলার খাবার বা ইফতারে পরিবারের বেশিরভাগ সদস্য একসাথে বসেন, সেটিই গুনুন।"}'::jsonb, '{"en":"Eating together without screens is a simple daily chance to talk, show healthy eating and stay close — even if it is only one meal a day.","bn":"স্ক্রিন ছাড়া একসাথে খাওয়া কথা বলার, স্বাস্থ্যকর খাওয়া দেখিয়ে শেখানোর আর কাছাকাছি থাকার সহজ রোজকার সুযোগ — দিনে মাত্র এক বেলা হলেও।"}'::jsonb, '{}'::jsonb, '🍽️', 'times', 'tap', 1, 7, 'at_least', 'week', 'family', NULL, NULL, 'any', 5, 'bonding', NULL, 'in_review'::lp_review_status, 10114)
